const views={changes:['∆','Inventory changes','Inventory change review','Compare a fresh snapshot before adopting it into the current workspace.'],acceptance:['✓','Application acceptance','Application acceptance workbook','Define pilot behavior, assign owners and review reported source/target results.'],project:['▱','Project & bundle','Project files & migration bundle','Save your workspace, resume it later, and export a consolidated review package.'],overview:['◫','Overview','Migration overview','Understand the path to VKS before you move a workload.'],inventory:['▦','Workload inventory','Workload inventory','Explore the resources and images discovered in your source inventory.'],dependencies:['⤳','Dependencies','Application dependencies','Declared relationships, unresolved references, and evidence gaps.'],findings:['⊙','Assessment','Compatibility assessment','Evidence-backed findings with actions and validation requirements.'],security:['◇','Security workbench','Security mapping & evidence','Map controls, define source/target cases, and track unresolved evidence.'],plan:['≡','Migration plan','Migration plan','Ordered workstreams with prerequisites and validation gates.'],compare:['⇄','Target comparison','Source → target comparison','Compare collected evidence and map destination classes.'],images:['▣','Image migration','Image Migration Manager','Plan registry reuse or copying, import results, and supply pilot image references.'],routing:['⇢','Ingress & gateways','Routing migration workbench','Map ingress to a destination class or existing Gateway listener.'],storage:['▤','Stateful & data','Stateful data migration planner','Map storage, define recovery targets, and plan consistent cutover and failback.'],gitops:['⑂','GitOps handoff','Kustomize & Argo CD handoff','Package the selected pilot as a reviewable repository scaffold with manual synchronization.'],pilot:['▷','Stateless pilot','Stateless pilot builder','Generate a reviewable Deployment and ClusterIP Service draft.'],target:['⚙','Target preflight','Target preflight & assumptions','Export local target checks, import observations, and review destination assumptions.']};
const P=MigrationPreflight, B=MigrationPilot, I=MigrationImages, R=MigrationRouting, S=MigrationSecurity, J=MigrationProject, T=MigrationStorage, G=MigrationGitOps, C=MigrationTargetChecks, W=MigrationJourney, A=MigrationAcceptance, D=MigrationChanges, Q=MigrationWaves, X=MigrationExecution, H=MigrationHandoff;
