const targetCheckPlan=()=>C.plan(raw,targetRaw,{revision:securityRevision,settings:targetCheckSettings,pilot:{workload:pilotChoice,images:{...imagePilotRefs,...pilotImages},serviceAccount:pilotSA},routing:{source:routeChoice,mode:routeMode,ingressClass:routeClass,gateway:routeGateway,gatewayNamespace:routeGatewayNS,listener:routeListener}});
let gitopsSettings=G.settings(),gitopsError='';
const gitopsBundle=()=>G.generate(raw,targetRaw,{workload:pilotChoice,images:{...imagePilotRefs,...pilotImages},serviceAccount:pilotSA},{source:routeChoice,mode:routeMode,ingressClass:routeClass,gateway:routeGateway,gatewayNamespace:routeGatewayNS,listener:routeListener},gitopsSettings);
let storageSettings={},storageChoice='';
