let projectName='VKS migration project',projectNotes='',projectSavedAt='',projectWarnings=[],projectError='',bundleBusy=false,projectLoading=false;
function projectState(){return {source:raw,target:targetRaw,sourceMode:mode,targetName,profile,mappings,checks:[...checks],wavePlanning:waveSettings,execution:{settings:executionSettings,evidence:executionEvidence,observation:executionObservation,observationHistory:executionHistory,inspection:executionInspection,cleanup:executionCleanup},acceptance:{settings:acceptanceSettings,evidence:acceptanceEvidence},preflight:{settings:targetCheckSettings,evidence:targetCheckEvidence},gitops:gitopsSettings,storage:{decisions:storageSettings,choice:storageChoice},images:{policy:imageStrategy,prefix:imagePrefix,overrides:imageOverrides,pilotRefs:imagePilotRefs,evidence:imageEvidence},pilot:{choice:pilotChoice,images:pilotImages,serviceAccount:pilotSA},routing:{choice:routeChoice,mode:routeMode,ingressClass:routeClass,gateway:routeGateway,gatewayNamespace:routeGatewayNS,listener:routeListener},security:{revision:securityRevision,decisions:securityDecisions,choice:securityChoice,evidence:securityEvidence}};}
function projectSnapshot(){return J.create(projectState(),{name:projectName,notes:projectNotes});}
function applyProject(project){clearChangeReview();pilotPhase='prepare';checklistScope='All';const s=project.state;executionSettings=s.execution.settings;executionEvidence=s.execution.evidence;executionObservation=s.execution.observation;executionHistory=s.execution.observationHistory;executionInspection=s.execution.inspection;executionCleanup=s.execution.cleanup;executionError='';waveSettings=s.wavePlanning;waveChoice=waveSettings.waves[0].id;waveWorkload='';waveError='';waveTablePage=0;acceptanceSettings=s.acceptance.settings;acceptanceEvidence=s.acceptance.evidence;acceptanceError='';raw=s.source;targetRaw=s.target;report=project.report;mode=s.sourceMode;targetName=s.targetName;profile=s.profile;mappings=s.mappings;checks=new Set(s.checks);targetCheckSettings=s.preflight.settings;targetCheckEvidence=s.preflight.evidence;targetCheckError='';gitopsSettings=s.gitops;gitopsError='';storageSettings=s.storage.decisions;storageChoice=s.storage.choice;imageStrategy=s.images.policy;imagePrefix=s.images.prefix;imageOverrides=s.images.overrides;imagePilotRefs=s.images.pilotRefs;imageEvidence=s.images.evidence;pilotChoice=s.pilot.choice;pilotImages=s.pilot.images;pilotSA=s.pilot.serviceAccount;routeChoice=s.routing.choice;routeMode=s.routing.mode;routeClass=s.routing.ingressClass;routeGateway=s.routing.gateway;routeGatewayNS=s.routing.gatewayNamespace;routeListener=s.routing.listener;securityRevision=s.security.revision;securityDecisions=s.security.decisions;securityChoice=s.security.choice;securityEvidence=s.security.evidence;projectName=project.name;projectNotes=project.notes;projectSavedAt=project.savedAt;projectWarnings=project.warnings;securityError='';imageError='';targetError='';projectError='';filter='';severity='All';category='All';}

let securityRevision=globalThis.crypto?.randomUUID?.()||String(Date.now())+'-'+Math.random(),securityDecisions={},securityEvidence=null,securityChoice='',securityError='';
const securityPlan=()=>S.plan(raw,targetRaw,securityDecisions,securityRevision);
const securitySummary=()=>S.summary(securityPlan(),securityEvidence);
const invalidateSecurity=()=>{securityRevision=globalThis.crypto?.randomUUID?.()||String(Date.now())+'-'+Math.random();securityEvidence=null;securityError='';targetCheckEvidence=null;targetCheckError='';acceptanceEvidence=null;acceptanceError='';executionEvidence=null;executionObservation=null;executionHistory={records:[],truncated:false};executionInspection=null;executionCleanup=null;executionError='';checks.clear();};
const resetSecurity=()=>{securityDecisions={};securityChoice='';invalidateSecurity();};
let routeChoice='',routeMode='Ingress',routeClass='',routeGateway='',routeGatewayNS='',routeListener='';
const resetRouting=()=>{routeChoice='';routeMode='Ingress';routeClass='';routeGateway='';routeGatewayNS='';routeListener='';};
const routingBundle=()=>R.generate(raw,{source:routeChoice,mode:routeMode,ingressClass:routeClass,gateway:routeGateway,gatewayNamespace:routeGatewayNS,listener:routeListener,target:targetRaw});
let imageStrategy='Mirror to Harbor',imagePrefix='harbor.example.com/migrated',imageOverrides={},imageEvidence=null,imageError='',imagePilotRefs={};
const imagePlan=()=>I.plan(report.images,{policy:imageStrategy,prefix:imagePrefix,overrides:imageOverrides});
const clearImageEvidence=()=>{imageEvidence=null;imageError='';imagePilotRefs={};pilotImages={};invalidateSecurity();};
let pilotChoice='',pilotImages={},pilotSA='';
const resetPilot=()=>{pilotChoice='';pilotImages={};pilotSA='';};
const pilotBundle=()=>B.generate(raw,{workload:pilotChoice,images:{...imagePilotRefs,...pilotImages},serviceAccount:pilotSA,target:targetRaw});
let targetRaw=null,mappings={},targetName='',targetError='';
const effectiveProfile=()=>({...profile,kubernetes:/^v?1\.\d+/.test(targetRaw?.sourceVersion||'')?targetRaw.sourceVersion:profile.kubernetes});
const comparison=()=>P.compare(raw,targetRaw,mappings);
const migrationPlan=()=>P.buildPlan(report,comparison());
let raw, report, mode='Demo',view='overview',filter='',severity='All',category='All',inventoryTab='resources',profile={release:'Not specified',kubernetes:'1.33',cni:'Antrea',gateway:'AVI / NSX ALB',storage:'Target mapping required',imagePolicy:'Mirror to Harbor'},checks=new Set();
const badge=x=>`<span class="badge ${esc(x)}">${esc(x)}</span>`;
function download(name,body,type='application/json'){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500);}
function findingRows(arr){return arr.map(f=>`<tr class="clickrow" data-finding="${f.id}" tabindex="0"><td>${badge(f.severity)}</td><td><b>${esc(f.title)}</b><small>${esc(f.id)} · ${esc(f.resource)}</small></td><td>${esc(f.category)}</td><td>${esc(f.action)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No matching findings. This does not establish migration readiness.</td></tr>';}
function stats(){const count=s=>report.findings.filter(f=>f.severity===s).length;return `<div class="stats"><div class="stat"><small>Resources discovered</small><strong>${report.resources.length}</strong><div class="sub">${report.workloads.length} workloads · ${new Set(report.resources.map(r=>r.metadata.namespace).filter(Boolean)).size} namespaces</div></div><div class="stat danger"><small>Migration blockers</small><strong>${count('Blocker')}</strong><div class="sub">Require explicit resolution</div></div><div class="stat"><small>Review required</small><strong>${count('Review')}</strong><div class="sub">Mapping and behavior validation</div></div><div class="stat"><small>Evidence gaps</small><strong>${count('Unknown')}</strong><div class="sub">Unknown is not a pass</div></div></div>`;}
function journeySummary(){const candidate=B.candidates(raw).some(x=>x.id===pilotChoice),p=candidate?pilotBundle():null;return W.summarize({demo:mode==='Demo',hasTarget:!!targetRaw,resources:report.resources.length,findings:report.findings.length,blockers:report.findings.filter(f=>f.severity==='Blocker').length,pilot:p?{...p,workload:pilotChoice}:null,hasPreflight:!!targetCheckEvidence,preflight:C.summary(targetCheckPlan(),targetCheckEvidence),security:securitySummary(),acceptance:acceptanceSummary(),pilotLifecycle:X.lifecycle(executionPlan(),executionEvidence,executionObservation,executionInspection,executionCleanup)});}
function handoffReview(){return H.build({projectName,demo:mode==='Demo',hasTarget:!!targetRaw,pilotSelected:B.candidates(raw).some(x=>x.id===pilotChoice),journey:journeySummary(),executionPlan:executionPlan(),receipt:executionEvidence,history:executionHistory,inspection:executionInspection,cleanup:executionCleanup,preflight:C.summary(targetCheckPlan(),targetCheckEvidence),security:securitySummary(),securityEvidence,acceptance:acceptanceSummary(),storage:storagePlan(),inventoryBlockers:report.findings.filter(f=>f.severity==='Blocker')});}
function handoffWorkbench(){const r=handoffReview();return `<section class="panel" id="pilot-handoff"><div class="panelhead"><div><h2>Guided pilot handoff</h2><p>${esc(r.scope.workload||'No pilot selected')} · ${esc(r.lifecycle.status)} · production gate closed</p></div><a class="textlink" href="#pilot">Review pilot →</a></div><p>Review the current gaps and pass the matching project and bundle to the next owner. Inventory-wide work is shown separately from the selected pilot. This review uses saved form settings and imported records.</p><div class="toolbar"><button data-action="handoffmd">↓ Handoff review Markdown</button><button class="secondary" data-action="handoffjson">↓ Handoff review JSON</button></div><div class="notice"><b>Next: ${esc(r.next.action)}</b><p>${esc(r.next.reason)}</p><a class="textlink" href="#${esc(r.next.view)}">Open workbench →</a></div><h3>Reported evidence dates</h3><div class="tablewrap"><table><thead><tr><th>Evidence area</th><th>Dated records</th><th>Earliest / latest reported time</th></tr></thead><tbody>${r.evidenceDates.map(e=>`<tr><td>${esc(e.area)}</td><td>${e.records}</td><td>${esc(e.earliest||'No dated evidence')}<small>${esc(e.latest)}</small></td></tr>`).join('')}</tbody></table></div><p>Run reported: ${esc(r.observations.runReportedAt||'None')}. Latest retained observation: ${esc(r.observations.latestAt||'None')}. Inspection: ${esc(r.observations.inspectionAt||'None')}. Cleanup: ${esc(r.observations.cleanupAt||'None')}. Dates do not prove evidence is current; rerun after relevant environment changes.</p>${r.sections.map(s=>`<details><summary>${esc(s.title)} · ${s.items.length} review items · ${esc(s.scope)}</summary><p>${esc(s.note)}</p><p>${esc(s.status)}. <a href="#${esc(s.view)}" class="textlink">Review workbench →</a></p>${s.items.length?`<div class="tablewrap"><table><thead><tr><th>Resource / case</th><th>Required review</th><th>Accountable reviewer</th></tr></thead><tbody>${s.items.slice(0,20).map(i=>`<tr><td>${esc(i.resource)}</td><td>${esc(i.reason)}${i.evidenceRef?`<small>${esc(i.evidenceRef)}</small>`:''}</td><td>${esc(i.owner)}</td></tr>`).join('')}</tbody></table></div>${s.items.length>20?`<p>Showing 20 of ${s.items.length}. Download the full handoff review for every item.</p>`:''}`:'<p>No recorded gaps here. Independent review remains required.</p>'}</details>`).join('')}<p>${esc(r.note)}</p><p>Role labels identify the required reviewer; they do not assign a person or record their approval. Use acceptance cases and data plans to record actual owners.</p></section>`;}
function workspaceContext(){return `<div class="workspace-context" aria-label="Current migration scope"><div><small>SOURCE</small><b>${mode==='Demo'?'Illustrative demo':'Imported snapshot'}</b><span>${report.resources.length} resources</span></div><div><small>DESTINATION</small><b>${targetRaw?'Snapshot imported':'Not supplied'}</b><span>${esc(targetName||'VKS · assumptions unverified')}</span></div><div><small>SELECTED PILOT</small><b>${esc(B.candidates(raw).some(x=>x.id===pilotChoice)?pilotChoice:'Not selected')}</b><a href="#pilot">Review scope →</a></div><div class="context-gate"><small>PRODUCTION GATE</small><b>Closed</b><span>Independent acceptance required</span></div></div>`;}
function actionChecklist(){const c=H.checklist(handoffReview()),rows=c.stages.filter(s=>checklistScope==='All'||s.scope===checklistScope);return `<section class="panel action-checklist"><div class="panelhead"><div><h2>Migration action checklist</h2><p>Scoped actions and reported evidence · production approval remains external</p></div><button class="secondary" data-action="checklistjson">↓ Export checklist</button></div><div class="toolbar" aria-label="Checklist scope">${['All','Selected pilot','Inventory','Project'].map(scope=>`<button class="pill ${checklistScope===scope?'active':''}" data-checklist-scope="${scope}" aria-pressed="${checklistScope===scope}">${scope}</button>`).join('')}</div>${rows.map((s,index)=>`<article class="checklist-row ${s.priority?'priority':''}"><div class="checklist-number">${String(c.stages.findIndex(x=>x.id===s.id)+1).padStart(2,'0')}</div><div class="checklist-content"><small>${esc(s.scope)}${s.priority?' · '+esc(s.priority):''}</small><h3>${esc(s.title)}</h3><b>${esc(s.status)}</b><p>${s.items.length} scoped review items. ${esc(s.note)}</p>${s.examples.length?`<details><summary>Show priority items</summary>${s.examples.map(i=>`<p><span class="mono">${esc(i.resource)}</span><br>${esc(i.reason)}</p>`).join('')}${s.items.length>3?'<p>Open the workbench or full handoff for all items.</p>':''}</details>`:''}</div><button class="secondary" data-checklist-view="${s.view}" ${s.phase?`data-checklist-phase="${s.phase}"`:''}>Open →</button></article>`).join('')}<p>${esc(c.note)}</p></section>`;}
function overview(){const j=journeySummary(),nextPhase=j.pilotLifecycle?.recoveryRequired?'recover':j.pilot?.blockers||!j.pilot?'prepare':j.pilotLifecycle?.requiresPilotRun?'run':'observe';return `<section class="next-action"><div class="eyebrow">NEXT ACTION · ${mode==='Demo'?'DEMO WORKSPACE':'CURRENT WORKSPACE'}</div><h2>${esc(j.next.action)}</h2><p>${esc(j.next.reason)}</p>${j.next.importSource?'<button data-action="import">＋ Import source inventory</button>':`<button class="action-link" data-checklist-view="${j.next.view}" ${j.next.view==='pilot'?`data-checklist-phase="${nextPhase}"`:''}>Open workbench →</button>`}<a class="textlink" href="#project">Open, save or review pilot handoff →</a></section>${actionChecklist()}<details class="panel"><summary>Migration flow reference</summary><div class="panelhead"><div><h2>Your migration flow</h2><p>Planning and reported evidence · production gate remains closed</p></div><a class="textlink" href="#plan">Full migration plan →</a></div><div class="journey-grid">${j.stages.map((x,i)=>`<a class="journey-card" href="#${x.view}"><small>0${i+1} · ${esc(x.scope)}</small><h3>${esc(x.title)}</h3><b>${esc(x.status)}</b><p>${esc(x.detail)}</p><span class="textlink">Review →</span></a>`).join('')}</div></details><div class="grid"><section class="panel"><h2>Selected pilot scope</h2>${j.pilot?`<p class="mono">${esc(j.pilot.workload)}</p><p>${j.pilot.blockers} transformation blockers · ${j.pilot.unverifiedPrerequisites} unverified prerequisites</p><p>Draft counts apply only to this workload and its generated resources.</p>`:'<p>No pilot selected. Choose a Deployment to define draft and preflight scope.</p>'}<a class="textlink" href="#pilot">Review pilot →</a></section><section class="panel"><h2>Additional workstreams</h2><p>Image registry access, routing behavior and stateful data require their own review and evidence. A stateless pilot does not close these inventory-wide workstreams.</p><div class="toolbar"><a class="textlink" href="#images">Images →</a><a class="textlink" href="#routing">Routing →</a><a class="textlink" href="#storage">Stateful data →</a><a class="textlink" href="#gitops">GitOps handoff →</a></div></section></div><h2>Inventory-wide assessment</h2><p><a class="textlink" href="#changes">Review fresh snapshot changes →</a></p><p>Open rule findings across the source snapshot. Draft mappings and imported results do not close these findings automatically.</p>${stats()}<section class="panel"><div class="panelhead"><h2>Inventory blockers to review</h2><a class="textlink" href="#findings">All findings →</a></div>${report.findings.filter(f=>f.severity==='Blocker').slice(0,4).map(f=>`<div class="finding" data-finding="${esc(f.id)}" tabindex="0">${badge(f.severity)}<div><b>${esc(f.title)}</b><p>${esc(f.resource)}</p></div></div>`).join('')||'<p>No rule-detected blockers. Coverage and acceptance remain unverified.</p>'}</section>`;}
function inventory(){return `<div class="tabs"><button class="pill ${inventoryTab==='resources'?'active':''}" data-tab="resources">Resources · ${report.resources.length}</button><button class="pill ${inventoryTab==='images'?'active':''}" data-tab="images">Container images · ${report.images.length}</button></div><div class="panel"><div class="toolbar"><input id="search" type="search" placeholder="Search kind, namespace, name or image…" value="${esc(filter)}" aria-label="Search inventory"></div><div class="tablewrap" id="results"></div></div><p><a href="#changes" class="textlink">Compare a fresh source or target snapshot →</a></p><div class="notice">Image accessibility, digests, architecture, signatures and vulnerability status are unverified. No images have been copied.</div>`;}
function tableInventory(){if(inventoryTab==='images'){const arr=report.images.filter(x=>JSON.stringify(x).toLowerCase().includes(filter.toLowerCase()));return `<table><thead><tr><th>Image reference</th><th>Workloads</th><th>Registry strategy</th><th>Validation</th></tr></thead><tbody>${arr.map(x=>`<tr><td class="mono">${esc(x.image)}<small>${x.image.includes('@sha256:')?'Digest pinned':'Mutable reference'}</small></td><td>${x.workloads.map(esc).join('<br>')}</td><td>${esc(profile.imagePolicy)}</td><td>${badge('Unknown')}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No matching images.</td></tr>'}</tbody></table>`;}
return `<table><thead><tr><th>Resource</th><th>Namespace</th><th>API version</th><th>Findings</th></tr></thead><tbody>${report.resources.filter(r=>E.id(r).toLowerCase().includes(filter.toLowerCase())).map(r=>`<tr class="clickrow" tabindex="0" data-resource="${esc(E.id(r))}"><td><b>${esc(r.metadata.name)}</b><small>${esc(r.kind)}</small></td><td>${esc(r.metadata.namespace||'Cluster scope')}</td><td class="mono">${esc(r.apiVersion||'Unknown')}</td><td>${report.findings.filter(f=>f.resource===E.id(r)).length} <span class="muted">to review</span></td></tr>`).join('')||'<tr><td colspan="4" class="empty">No matching resources.</td></tr>'}</tbody></table>`;}
function assessment(securityOnly=false){const categories=[...new Set(report.findings.map(f=>f.category))].sort();return `<div class="banner"><div><strong>${securityOnly?'No control is marked equivalent without behavioral tests':'Assessment engine · v0.20'}</strong><p>${securityOnly?'Policy objects reveal intent. Target enforcement, identity mappings and exclusions remain unverified.':'Rule-based inventory review. Each finding includes its evidence, action and validation requirement. This is not an exhaustive support matrix.'}</p></div>${badge('Read-only')}</div>${securityOnly?'':stats()}<section class="panel"><div class="toolbar"><input id="search" type="search" placeholder="Search findings or resources…" aria-label="Search findings" value="${esc(filter)}"><select id="severity" aria-label="Severity">${['All','Blocker','Review','Unknown'].map(s=>`<option ${s===severity?'selected':''}>${s}</option>`).join('')}</select>${securityOnly?'':`<select id="category" aria-label="Category"><option>All</option>${categories.map(s=>`<option ${s===category?'selected':''}>${esc(s)}</option>`).join('')}</select>`}<span class="muted">Click a finding for evidence</span></div><div class="tablewrap"><table><thead><tr><th>Severity</th><th>Finding & resource</th><th>Area</th><th>Required action</th></tr></thead><tbody id="results"></tbody></table></div></section>${securityOnly?'<section class="panel"><h2>Security validation contract</h2><p>Admission: known allowed and denied manifests. Network: allowed and denied connectivity. RBAC: SubjectAccessReview for remapped identities. Secrets: successful authorized retrieval without exposing values. Mesh: mTLS identity and authorization tests.</p><a class="textlink" target="_blank" rel="noopener" href="https://kubernetes.io/docs/concepts/services-networking/network-policies/">Kubernetes NetworkPolicy enforcement requirements ↗</a></section>':'<p class="muted">Live exports may return current API versions even when obsolete manifests remain in Git. Audit the desired-state repository separately.</p>'}`;}
function filteredFindings(){return report.findings.filter(f=>(view!=='security'||['Security','Identity','Secrets'].includes(f.category))&&(severity==='All'||f.severity===severity)&&(view==='security'||category==='All'||f.category===category)&&JSON.stringify(f).toLowerCase().includes(filter.toLowerCase()));}
function dependencies(){const apps=report.workloads;return `<div class="banner"><div><strong>Declared dependencies · ${report.edges.length} connections</strong><p>References and label selectors are observed from manifests. External call paths and business dependencies require telemetry or owner confirmation.</p></div>${badge('Partial coverage')}</div><section class="panel"><div class="toolbar"><select id="appSelect" aria-label="Select workload"><option value="">All relationships</option>${apps.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select></div><div id="graph"></div></section><section class="panel"><h2>What this inventory cannot tell you</h2><p>Database consistency, application API calls, S3/RDS usage hidden in configuration, DNS behavior, latency, TLS trust and physical NAD connectivity. These require additional evidence.</p></section>`;}
function graph(app=''){let edges=report.edges.filter(e=>!app||e.from===app||e.to===app);$('#graph').innerHTML=edges.map(e=>`<div class="edge"><div class="node mono">${esc(e.from)}</div><div class="edgelabel">${esc(e.type)} →<br>${esc(e.confidence)}</div><div class="node mono">${esc(e.to)}</div></div>`).join('')||'<p class="empty">No declared relationships found in this scope.</p>';}
const waves=[['Evidence & target prerequisites','Close collection gaps; confirm VKS release, Kubernetes version, controllers, identity, CSI, capacity and external dependencies.',['Target release support checked','Inventory gaps reviewed','External dependencies confirmed']],['Platform & security foundations','Provision compatible controllers, registry credentials, secret providers, admission controls and network policy before application deployment.',['Controllers and CRDs available','Identity mappings reviewed','Allow/deny security tests pass']],['Images & desired state','Resolve image digests, choose registry strategy, map ingress/storage, and update GitOps overlays without competing reconciliation.',['Target image pulls pass','GitOps destination reviewed','Routing and storage mapping approved']],['Stateless pilot','Choose a representative stateless workload. Validate application behavior, scaling, observability and permitted/denied connectivity.',['Smoke and acceptance tests pass','Load and capacity validated','Recovery procedure exercised']],['Stateful migration','Use workload-specific replication or consistent backup/restore. Agree RPO/RTO, write quiescence, integrity checks and reverse synchronization.',['Backup restore proven','Consistency and integrity validated','Rollback after new writes planned']],['Controlled cutover & protection','Shift traffic with DNS and certificate readiness, observe SLOs, secure owner acceptance and activate destination protection.',['DNS/TLS and traffic tests pass','Application owner acceptance','Destination backups and DR verified']]];
function wavePlanner(){const p=wavePlan();if(!p.waves.some(w=>w.id===waveChoice))waveChoice=p.waves[0].id;if(!p.workloads.some(r=>r.id===waveWorkload))waveWorkload=p.workloads[0]?.id||'';const selected=p.waves.find(w=>w.id===waveChoice),work=p.workloads.find(r=>r.id===waveWorkload),field=(k,label)=>`<label>${label}<textarea name="${k}" rows="3" maxlength="8000">${esc(selected[k])}</textarea></label>`;return `<section class="panel"><div class="panelhead"><div><h2>Workload migration waves</h2><p>${p.workloads.length-p.unassigned.length} of ${p.workloads.length} workloads assigned · ${p.dependencyIssues.length} sequencing reviews · production gate closed</p></div><div class="toolbar"><button class="secondary" data-action="wavejson">↓ Wave plan JSON</button><button class="secondary" data-action="wavemd">↓ Wave runbook</button></div></div><p>Explicitly group workloads and record the prerequisites that owners confirm. Wave names and order are a plan; shared infrastructure and external application calls are not inferred. Controller-owned Pods and Jobs are omitted; collect their controlling desired-state resources. Other observed workloads may still overlap application boundaries.</p><div class="error" role="alert">${esc(waveError)}</div><div class="wave-cards">${p.waves.map((w,i)=>`<div class="wave-card"><small>WAVE ${w.order}</small><h3>${esc(w.name)}</h3><p>${w.workloads.length} workloads · ${w.planningGaps} planning gaps</p><p>${w.statefulWorkloads.length} workloads with declared storage concerns · ${w.openBlockers} open resource blockers</p><p>${esc(w.owner||'Owner unassigned')} · ${esc(w.status)}</p><div class="toolbar"><button class="secondary" data-action="wavemove" data-wave-id="${esc(w.id)}" data-direction="-1" ${i===0?'disabled':''} aria-label="Move ${esc(w.name)} earlier">↑ Earlier</button><button class="secondary" data-action="wavemove" data-wave-id="${esc(w.id)}" data-direction="1" ${i===p.waves.length-1?'disabled':''} aria-label="Move ${esc(w.name)} later">↓ Later</button></div></div>`).join('')}</div><div class="toolbar"><button class="secondary" data-action="waveadd" ${p.waves.length>=12?'disabled':''}>＋ Add wave</button><label>Edit wave<select id="waveChoice">${p.waves.map(w=>`<option value="${esc(w.id)}" ${w.id===waveChoice?'selected':''}>${w.order}. ${esc(w.name)}</option>`).join('')}</select></label><button class="secondary" data-action="waveremove" ${p.waves.length===1?'disabled':''}>Remove empty selected wave</button></div><form id="waveDefinitionForm"><div class="formgrid"><label>Wave name<input name="name" maxlength="120" value="${esc(selected.name)}" required></label><label>Accountable wave owner<input name="owner" maxlength="200" value="${esc(selected.owner)}"></label>${field('entryCriteria','Entry criteria, prerequisite evidence and environment checks')}${field('exitCriteria','Exit criteria, acceptance evidence and owner decision')}${field('rollback','Rollback trigger, procedure, write-divergence handling and owner')}</div><button type="submit">Save wave definition</button></form></section><section class="panel"><h2>Assign workloads and explicit prerequisites</h2>${work?`<label>Workload<select id="waveWorkload">${p.workloads.map(r=>`<option value="${esc(r.id)}" ${r.id===waveWorkload?'selected':''}>${esc(r.id)}${r.id===pilotChoice?' · selected pilot':''}</option>`).join('')}</select></label><form id="waveAssignmentForm"><div class="formgrid"><label>Planned wave<select name="waveId"><option value="">Unassigned</option>${p.waves.map(w=>`<option value="${esc(w.id)}" ${w.id===work.waveId?'selected':''}>${w.order}. ${esc(w.name)}</option>`).join('')}</select></label><label>Application group<input name="application" maxlength="200" value="${esc(work.application)}"></label><label>Workload owner<input name="owner" maxlength="200" value="${esc(work.owner)}"></label><label>Required workloads (select up to 20; Ctrl/Cmd for multiple)<select name="dependsOn" multiple size="5">${p.workloads.filter(r=>r.id!==work.id).map(r=>`<option value="${esc(r.id)}" ${work.dependsOn.includes(r.id)?'selected':''}>${esc(r.id)}</option>`).join('')}</select></label><label>Retained services, external dependencies and ordering notes<textarea name="notes" rows="4" maxlength="8000">${esc(work.notes)}</textarea></label></div><p>${esc(work.storageReason)}</p><button type="submit">Save workload assignment</button></form>`:'<p>No supported workload resources observed. External applications and discovery gaps still need review.</p>'}<p>Dependencies are owner declarations, separate from the <a href="#dependencies">manifest reference view</a>. Earlier-wave placement records order only. Same-wave ordering, later-wave prerequisites and cyclic chains stay visible until the plan changes.</p></section><section class="panel"><h2>Wave assignment review</h2><div class="tablewrap"><table><thead><tr><th>Workload / application</th><th>Wave / owner</th><th>Planning and sequencing reviews</th><th>Open resource findings</th></tr></thead><tbody>${p.workloads.slice(waveTablePage*100,(waveTablePage+1)*100).map(r=>`<tr><td class="mono">${esc(r.id)}<small>${esc(r.application||'Application unassigned')}</small></td><td>${esc(p.waves.find(w=>w.id===r.waveId)?.name||'Unassigned')}<small>${esc(r.owner||'Owner unassigned')}</small></td><td>${r.gaps.map(esc).join('<br>')}${r.dependencyIssues.map(x=>`<p>${esc(x.type)}: <span class="mono">${esc(x.dependency)}</span></p>`).join('')}${!r.gaps.length&&!r.dependencyIssues.length?'No structural planning issues detected; acceptance remains open.':''}${r.stateful?'<p>Data consistency and recovery review required.</p>':''}</td><td>${r.openBlockerIds.length} blockers · ${r.openFindingIds.length} findings<small>${r.openFindingIds.map(esc).join(', ')||'No resource-scoped findings; global findings still apply'}</small></td></tr>`).join('')||'<tr><td colspan="4">No supported workloads observed.</td></tr>'}</tbody></table></div><div class="toolbar"><button class="secondary" data-action="waveprev" ${waveTablePage===0?'disabled':''}>Previous</button><span>Page ${waveTablePage+1} of ${Math.max(1,Math.ceil(p.workloads.length/100))}</span><button class="secondary" data-action="wavenext" ${(waveTablePage+1)*100>=p.workloads.length?'disabled':''}>Next</button></div><div class="notice">${esc(p.note)}</div><div class="toolbar"><a href="#storage" class="textlink">Data recovery →</a><a href="#security" class="textlink">Security evidence →</a><a href="#acceptance" class="textlink">Application acceptance →</a><a href="#project" class="textlink">Save project / export bundle →</a></div></section>`;}
function plan(){return `<div class="banner"><div><strong>A reviewable plan. No execution has occurred.</strong><p>Workstreams are a planning template informed by inventory findings. Define workload waves below, then review shared platform workstreams and acceptance requirements.</p></div><button class="secondary" data-action="planexport">↓ Export plan</button></div>${wavePlanner()}<section class="panel"><h2>Stateful data gate · Closed</h2><p>${storagePlan().rows.length} claim/template rows; data transfer and recovery remain unverified.</p><a href="#storage" class="textlink">Open stateful data planner →</a></section><section class="panel"><h2>Security parity gate · Closed</h2><p>${securitySummary().unresolved} observed controls unresolved. ${esc(securitySummary().reason)}</p><a href="#security" class="textlink">Open security mapping & evidence →</a></section>${generatedPlan()}${waves.map(([title,desc,tasks],i)=>`<div class="wave"><div class="wavenumber">${i+1}</div><section class="panel"><div class="panelhead"><h2>${esc(title)}</h2>${badge('Pending validation')}</div><p>${esc(desc)}</p>${tasks.map((t,j)=>`<label class="check"><input type="checkbox" data-check="${i}-${j}" ${checks.has(i+'-'+j)?'checked':''}>${esc(t)}</label>`).join('')}</section></div>`).join('')}<div class="notice">Checkboxes are session planning notes, not test results. Production readiness stays unverified. Stateful failback requires an explicit data-divergence strategy.</div>`;}
function compare(){
 const c=comparison(), classes=['StorageClass','IngressClass','GatewayClass'];
 const options=(kind,key,current)=>`<select data-mapping="${esc(key)}" aria-label="Target mapping for ${esc(key)}"><option value="">Keep source name / unresolved</option>${(targetRaw?.items||[]).filter(r=>r.kind===kind).map(r=>`<option value="${esc(r.metadata.name)}" ${current===r.metadata.name?'selected':''}>${esc(r.metadata.name)}</option>`).join('')}</select>`;
 const keys=new Map();for(const r of report.resources){const storage=r.kind==='PersistentVolumeClaim',ingress=r.kind==='Ingress',gateway=r.kind==='Gateway';if(!storage&&!ingress&&!gateway)continue;const n=storage?r.spec?.storageClassName:gateway?r.spec?.gatewayClassName:r.spec?.ingressClassName||r.metadata.annotations?.['kubernetes.io/ingress.class'];if(storage&&n==='')continue;const key=(storage?'storage:':gateway?'gateway:':'ingress:')+(n??'<default>');keys.set(key,{kind:storage?classes[0]:gateway?classes[2]:classes[1],name:n??'Unspecified/default'});}
 return `<div class="banner"><div><strong>${c.targetImported?'Destination inventory imported':'Import the destination inventory'}</strong><p>${c.targetImported?esc(targetName)+' · Kubernetes '+esc(c.targetVersion):'Run the same read-only collector against your target context. Assessment stays in this browser session.'}</p></div><button data-action="targetimport">${c.targetImported?'Replace target':'Import target JSON'}</button>${c.targetImported?'<button class="secondary" data-action="targetclear">Clear target</button>':''}</div><div class="error" role="alert">${esc(targetError)}</div><section class="panel"><h2>Collect evidence from both clusters</h2><pre>python3 collect.py --context SOURCE --output source.json
python3 collect.py --context TARGET --output target.json</pre><a href="collect.py" download class="textlink">↓ Download collector v0.4</a><p>Target comparison works best with the current collector, which records API discovery and successful resource queries. Older exports retain unknown coverage.</p></section><div class="stats"><div class="stat"><small>Observed evidence</small><strong>${c.rows.filter(r=>r.status==='Observed').length}</strong><div class="sub">Presence requires behavior validation</div></div><div class="stat danger"><small>Confirmed gaps</small><strong>${c.rows.filter(r=>r.status==='Blocker').length}</strong><div class="sub">Resolve before dependent deployment</div></div><div class="stat"><small>Unknowns</small><strong>${c.rows.filter(r=>r.status==='Unknown').length}</strong><div class="sub">Collect or test additional evidence</div></div><div class="stat"><small>Production gate</small><strong>Closed</strong><div class="sub">No target tests have run</div></div></div>${keys.size?`<section class="panel"><h2>Destination class mappings</h2><p>Choose an observed target class. A mapping records intent; it does not transform manifests or prove equivalent behavior.</p><div class="tablewrap"><table><thead><tr><th>Source requirement</th><th>Target class</th></tr></thead><tbody>${[...keys].map(([key,v])=>`<tr><td>${esc(v.kind)}<small>${esc(v.name)}</small></td><td>${options(v.kind,key,mappings[key])}</td></tr>`).join('')}</tbody></table></div></section>`:''}<section class="panel"><div class="panelhead"><h2>Evidence comparison</h2><button class="secondary" data-action="comparisonexport">↓ Export comparison</button></div><div class="tablewrap"><table><thead><tr><th>Status</th><th>Requirement</th><th>Observed evidence</th><th>Next validation</th></tr></thead><tbody>${c.rows.map(r=>`<tr><td>${badge(r.status)}</td><td><b>${esc(r.area)}</b><small>${esc(r.resource)}</small></td><td>${esc(r.evidence)}</td><td>${esc(r.action)}</td></tr>`).join('')}</tbody></table></div></section>`;
}
function generatedPlan(){const p=migrationPlan();return `<section class="panel"><h2>Inventory-informed sequence</h2><p>${esc(p.notes)}</p>${p.phases.map((phase,i)=>`<details class="phase" ${phase.workloads.length?'open':''}><summary><b>${i+1}. ${esc(phase.title)}</b> · ${phase.findings.length} findings · ${phase.targetGaps.length} target gaps · ${phase.workloads.length} workloads</summary><p>Prerequisites: ${phase.dependsOn.map(esc).join(', ')||'Start here'}. Status: pending validation.</p>${phase.findings.length?`<div class="findinglinks">${phase.findings.map(id=>`<button class="pill" data-finding="${id}">${id}</button>`).join(' ')}</div>`:''}${phase.targetGaps.map(g=>`<p>${badge(g.status)} ${esc(g.resource)} · ${esc(g.evidence)}</p>`).join('')}${phase.workloads.map(w=>`<div class="workitem"><b class="mono">${esc(w.resource)}</b><p>${esc(w.classification)}${w.blockers.length?' · Blockers: '+w.blockers.map(esc).join(', '):''}</p><p>Declared dependencies: ${w.dependencies.map(esc).join(' · ')||'None discovered; verify with owner'}</p></div>`).join('')}</details>`).join('')}<a href="#compare" class="textlink">Review source → target evidence →</a></section>`;}
function gitops(){const p=gitopsBundle(),c=gitopsSettings,field=(key,label)=>`<label>${label}<input name="${key}" value="${esc(c[key])}" maxlength="1000" ${key==='repoPath'?'':'required'}></label>`;
 return `<div class="banner"><div><strong>Kustomize scaffold + manual-sync Argo CD Application</strong><p>Selected pilot: ${esc(pilotChoice||'None — select one in Stateless pilot')}. This handoff uses sanitized inventory; reconcile it with complete Helm/Git desired state before any deployment.</p></div>${badge('Production gate closed')}</div><section class="panel"><h2>1. Repository and destination</h2><form id="gitopsForm"><div class="formgrid">${field('repoURL','HTTPS repository URL (no credentials)')}${field('revision','Git revision / branch')}${field('repoPath','Repository subdirectory (empty for root)')}${field('applicationName','Argo CD Application name')}${field('argoNamespace','Argo CD namespace')}${field('argoProject','Argo CD project')}${field('clusterName','Destination cluster name registered in Argo CD')}</div><label class="check"><input name="includeRouting" type="checkbox" ${c.includeRouting?'checked':''}>Include the currently selected routing draft</label><button type="submit">Update GitOps package</button></form><div class="error" role="alert">${esc(gitopsError)}</div><p>Only the selected Deployment and matching isolated Services are packaged. Routing must refer to Services in this pilot scope. No ApplicationSet, operator, Helm chart, credentials, namespace policy or stateful data is generated.</p><div class="toolbar"><a href="#pilot" class="textlink">Configure pilot →</a><a href="#routing" class="textlink">Configure routing →</a><a href="#security" class="textlink">Review security prerequisites →</a></div></section><section class="panel"><div class="panelhead"><h2>2. Review package</h2>${badge(p.review.blockers.length?'Blocker':'Unverified')}</div><p>${esc(p.review.status)} · ${p.expected.items.length} expected resources · ${p.patches.length} destination patch operation(s).</p>${p.review.blockers.map(b=>`<div class="notice"><span class="mono">${esc(b.resource)}</span><p>${esc(b.reason)}</p></div>`).join('')}<h3>Package files</h3><div class="tablewrap"><table><thead><tr><th>Path</th><th>Purpose</th></tr></thead><tbody>${p.files.map(f=>`<tr><td class="mono">${esc(f.name)}</td><td>${f.name.includes('kustomization')?'Kustomize resources / destination patches':f.name.includes('application.json')?'Argo CD draft — automated sync omitted':f.name.includes('expected-resources')?'Expected-object fixture; not an actual render':f.name.includes('review')?'Blockers and prerequisites':f.name.endsWith('.sh')?'Render, server dry-run and diff only':'Reviewable source / documentation'}</td></tr>`).join('')}</tbody></table></div><details><summary>Destination patches</summary><pre>${esc(JSON.stringify(p.patches,null,2))}</pre></details><details><summary>Argo CD Application draft</summary><pre>${esc(JSON.stringify(p.application,null,2))}</pre></details>${p.review.notes.map(n=>`<p>${esc(n)}</p>`).join('')}<div class="notice">${esc(p.review.renderVerification)} Actual Argo CD registration, policy, ownership, image pulls and application/security behavior remain unverified.</div></section><section class="panel"><h2>3. Export and validate</h2><div class="toolbar"><button data-action="gitopszip">↓ GitOps handoff ZIP</button><button class="secondary" data-action="gitopsreview">↓ gitops-review.json</button><a href="#project" class="textlink">Save settings in project / full migration bundle →</a></div><pre># From the extracted package root
bash validate-gitops.sh TARGET_CONTEXT</pre><p>The script stops on known blockers. Otherwise it renders repository/overlays/vks, performs server dry-run, and shows a diff. Do not build/sync the base alone; the destination mappings are in the overlay.</p><p>Copy repository/ contents into the configured repository subdirectory only after reconciling desired state. Review the Application separately with its owner. Manual synchronization would deploy resources; this app does not publish to Git, install an Application or synchronize workloads.</p><a href="https://argo-cd.readthedocs.io/en/latest/user-guide/application-specification/" target="_blank" rel="noopener" class="textlink">Argo CD Application reference ↗</a></section>`;
}
function storage(){const p=storagePlan();if(!p.rows.some(r=>r.id===storageChoice))storageChoice=p.rows[0]?.id||'';const c=p.rows.find(r=>r.id===storageChoice),d=storageSettings[storageChoice]||{},classes=(targetRaw?.items||[]).filter(r=>r.kind==='StorageClass');const field=(name,label,type='text',min='')=>`<label>${label}<input name="${name}" type="${type}" ${min!==''?`min="${min}" step="any"`:''} value="${esc(d[name]||'')}" ${name==='targetClass'?'list="storageClasses"':''}></label>`,area=(name,label)=>`<label>${label}<textarea name="${name}" rows="3" maxlength="8000">${esc(d[name]||'')}</textarea></label>`;
 return `<div class="banner"><div><strong>Data migration gate · Closed</strong><p>Inventory and planning only. Replication, backup/restore, consistency checks and recovery must be executed through application-supported procedures outside this app.</p></div>${badge('Data movement not executed')}</div><section class="panel"><h2>Persistent data inventory</h2><p>Observed claims and claim templates are separate evidence. Template rows can overlap materialized PVCs; reconcile actual claims before counting capacity or scheduling transfers.</p><div class="tablewrap"><table><thead><tr><th>Claim / template</th><th>Source request / class</th><th>Declared consumers</th><th>Plan status</th></tr></thead><tbody>${p.rows.map(r=>`<tr><td><button class="pill" data-storage-claim="${esc(r.id)}">${esc(r.id)}</button><small>${esc(r.kind)}</small></td><td>${esc(r.request)} · ${esc(r.sourceClass)}<small>${r.accessModes.map(esc).join(', ')} · ${esc(r.volumeMode)}</small></td><td class="mono">${r.consumers.map(esc).join('<br>')||'None observed; not proof of no use'}<small>${esc(r.consumerEvidence)}</small></td><td>${esc(r.status)}<small>${r.blockers.length} blockers · ${r.missing.length} planning gaps</small></td></tr>`).join('')||'<tr><td colspan="4">No PVCs or claim templates observed. External state and collection gaps still require owner review.</td></tr>'}</tbody></table></div></section>${c?`<section class="panel"><h2>Map and plan: ${esc(c.name)}</h2><p>Namespace preserved: ${esc(c.namespace)}. ${c.kind==='VolumeClaimTemplate'?`Declared replicas: ${esc(c.replicas)} · starting ordinal: ${esc(c.startOrdinal)} · map each ordinal claim separately in your notes.`:'Target name defaults to the source PVC name.'}</p><p>Source reclaim behavior: ${esc(c.reclaimPolicy)}${c.retention?' · StatefulSet retention '+esc(JSON.stringify(c.retention)):''}. No deletion, retention or binding setting is changed.</p><form id="storageForm"><div class="formgrid">${field('targetClass','Destination StorageClass')}<datalist id="storageClasses">${classes.map(x=>`<option value="${esc(x.metadata.name)}">`).join('')}</datalist>${c.kind==='PersistentVolumeClaim'?field('targetPVC','Destination PVC name (optional; same namespace)'):''}<label>Transfer strategy<select name="strategy"><option value="">Choose application-supported strategy</option>${T.STRATEGIES.map(x=>`<option ${d.strategy===x?'selected':''}>${x}</option>`).join('')}</select></label>${field('owner','Application / data owner')}${field('group','Consistency group (explicit planning label)')}${field('rpoMinutes','Target RPO (minutes; zero allowed)','number','0')}${field('rtoMinutes','Target RTO (minutes)','number','0.000001')}${field('measuredRpoMinutes','Reported measured data-loss window (minutes)','number','0')}${field('measuredRestoreMinutes','Reported measured complete recovery duration (minutes)','number','0')}${area('quiesce','Writer fencing, quiescence and final synchronization')}${area('rollbackAfterWrites','Failback after destination writes / reverse synchronization')}${field('backupEvidence','Backup/recovery point evidence reference')}${field('restoreEvidence','Restore rehearsal evidence reference')}${field('integrityEvidence','Application/data integrity evidence reference')}${field('rollbackEvidence','Failback rehearsal evidence reference')}${field('portabilityEvidence','CSI snapshot portability evidence (required for snapshot strategy)')}${area('notes','Operator support, ordinal claim mapping, topology and recovery notes')}</div><button type="submit">Save data migration plan</button></form><p>References and measured values are owner-reported planning inputs, not authenticated validation. Destination class presence does not prove capacity or access-mode support.</p></section><section class="panel"><h2>Claim assessment</h2>${c.blockers.map(x=>`<div class="notice">${badge('Blocker')} ${esc(x)}</div>`).join('')}${c.missing.length?`<p>Required planning fields: ${c.missing.map(esc).join(', ')}</p>`:''}<p>Missing evidence references: ${c.evidenceMissing.map(esc).join(', ')||'None recorded as missing; external references still require review'}</p>${c.unknowns.map(x=>`<p>• ${esc(x)}</p>`).join('')}<p>Target class observed: ${c.targetClassObserved?'Yes':'No'} · provisioner: ${esc(c.targetProvisioner||'Unknown')} · target claim observed: ${c.targetPVCObserved?'Yes':'No'}.</p></section>`:''}<section class="panel"><h2>Consistency groups & discovery gaps</h2>${p.groups.map(g=>`<div class="workitem"><b>${esc(g.name)}</b><p>${g.claims.map(esc).join(' · ')}</p><p>${esc(g.requirement)}</p></div>`).join('')||'<p>No consistency groups planned.</p>'}${p.gaps.map(g=>`<div class="notice"><span class="mono">${esc(g.resource)}</span><p>${esc(g.reason)}</p></div>`).join('')}<p>Hidden database, SaaS, object-store and operator-managed dependencies are not ruled out by a clean volume inventory.</p></section><section class="panel"><h2>Cutover and recovery checkpoints</h2>${p.steps.map((s,i)=>`<div class="workitem"><b>${i+1}. ${esc(s.phase)}</b><p>${esc(s.requirement)}</p></div>`).join('')}<div class="notice">Accepting writes on the target is a data-divergence checkpoint. Reversing DNS alone cannot reconcile those writes or make failback safe.</div><div class="toolbar"><button data-action="storageexport">↓ stateful-plan.json</button><button class="secondary" data-action="storagemd">↓ stateful-runbook.md</button><a href="#project" class="textlink">Save in project / export migration ZIP →</a></div><a href="https://kubernetes.io/docs/concepts/storage/volume-snapshots/" target="_blank" rel="noopener" class="textlink">Kubernetes volume snapshots and topology ↗</a></section>`;
}
function acceptanceWorkbench(){const p=acceptancePlan(),summary=acceptanceSummary(),c=p.cases.find(x=>x.id===acceptanceChoice)||p.cases[0];return `<div class="banner"><div><strong>Application behavior requires its own evidence</strong><p>Define comparable source and target tests for the selected pilot. Procedures are documentation; execute approved tests outside this app.</p></div>${badge('Production gate closed')}</div><div class="error" role="alert">${esc(acceptanceError)}</div>${!p.workload?'<div class="notice">No pilot selected. <a href="#pilot">Choose a Deployment</a> before importing results.</div>':`<p>Pilot: <span class="mono">${esc(p.workload)}</span> · <a href="#pilot" class="textlink">Review scope →</a></p>`}<section class="panel"><h2>1. Bind source and target contexts</h2><form id="acceptanceContextsForm"><div class="formgrid"><label>Source context<input name="sourceContext" value="${esc(p.sourceContext)}" maxlength="300" required></label><label>Target context<input name="targetContext" value="${esc(p.targetContext)}" maxlength="300" required></label></div><p>Use distinct explicit context names. ${targetCheckSettings.context?'Configured target preflight context: <b>'+esc(targetCheckSettings.context)+'</b>. ':''}Names are labels, not proof of cluster identity; cross-check the <a href="#target">target preflight</a> and current environment. No context switch occurs.</p><button type="submit">Save acceptance contexts</button></form>${!p.contextsReady?'<p class="notice">Distinct source and target contexts are required before importing records. The target must match the target preflight context when configured.</p>':''}</section><section class="panel"><div class="panelhead"><div><h2>2. Define acceptance cases</h2><p>${summary.reportedComplete} of ${summary.total} cases have reported source/target matches. This is evidence coverage, not readiness.</p></div></div><div class="tabs acceptance-tabs">${p.cases.map(x=>`<button class="pill ${c.id===x.id?'active':''}" data-acceptance-case="${x.id}">${esc(x.title)}</button>`).join('')}</div><h3>${esc(c.title)}</h3><p>${esc(c.guidance)}</p><form id="acceptanceCaseForm"><div class="formgrid"><label>Accountable reviewer / owner<input name="owner" value="${esc(c.owner)}" maxlength="200" required></label><label>Measurable expected result<textarea name="expected" rows="4" maxlength="8000" required>${esc(c.expected)}</textarea></label><label>Approved procedure and test scope<textarea name="procedure" rows="5" maxlength="8000" required>${esc(c.procedure)}</textarea></label></div><button type="submit">Save case definition</button></form><p>Use comparable transactions and measurements on each side. Expected outcomes may differ by documented platform design; explain equivalence explicitly. Procedures can involve disruption: obtain environment owner authorization before running them. This app runs no command.</p></section><section class="panel"><h2>3. Export workbook and record template</h2><p>Define owners, procedures and expected results before testing. Populate the JSON template with Pass, Fail, Error or NotRun; executed records require an observation timestamp with timezone, detail and an evidence reference. Pass is an owner-reported comparison against the defined expectation. Errors never count as passes.</p><div class="toolbar"><button data-action="acceptanceplan">↓ acceptance-plan.json</button><button class="secondary" data-action="acceptancetemplate">↓ Evidence template</button><button class="secondary" data-action="acceptancemd">↓ Acceptance workbook</button></div><p>Revision: <span class="mono">${esc(p.planRevision)}</span>. Changing cases, pilot, inventories or relevant mappings clears imported results. Records are historical snapshots; rerun after environment changes. Keep credentials and sensitive logs out of this workbook; use reviewable artifact references.</p></section><section class="panel"><div class="panelhead"><h2>4. Review reported outcomes</h2><button data-action="acceptanceimport">Import acceptance evidence</button></div><div class="tablewrap"><table><thead><tr><th>Case / owner</th><th>Source outcome</th><th>Target outcome</th><th>Review status</th></tr></thead><tbody>${summary.rows.map(x=>`<tr><td>${esc(x.title)}<small>${esc(x.owner||'Unassigned')} · ${x.configured?'Definition recorded':'Definition incomplete'}</small></td>${['source','target'].map(side=>`<td>${esc(x[side]?.status||'NotRun')}<small>${esc(x[side]?.observedAt||'')}</small><small>${esc(x[side]?.detail||'No observation')}</small><small>${esc(x[side]?.evidenceRef||'No reference')}</small></td>`).join('')}<td>${esc(x.status)}</td></tr>`).join('')}</tbody></table></div><div class="notice">${esc(summary.reason)} Even twelve reported passes cannot open the production gate.</div><div class="toolbar"><button class="secondary" data-action="acceptancereview">↓ acceptance-review.json</button><a class="textlink" href="#security">Security evidence →</a><a class="textlink" href="#storage">Data recovery →</a><a class="textlink" href="#project">Save project / migration bundle →</a></div></section>`;}
function projectView(){return `<div class="banner"><div><strong>${esc(projectName)}</strong><p>Save a portable project JSON to preserve inventories, target assumptions, mappings, selected drafts, checklist notes, stateful data plans, application acceptance cases, local pilot receipts, and external evidence. Resume by opening that file. Processing stays in this browser tab.</p></div>${badge('Production gate closed')}</div><section class="panel"><h2>Project details</h2><form id="projectForm"><div class="formgrid"><label>Project name<input name="name" value="${esc(projectName)}" maxlength="120" required></label><label>Project notes<textarea name="notes" rows="3" maxlength="8000">${esc(projectNotes)}</textarea></label></div><button type="submit">Update project details</button></form><p>Last saved/restored snapshot: ${esc(projectSavedAt||'None in this session')}. Subsequent edits require another Save project; there is no automatic storage.</p></section><div class="grid"><section class="panel"><h2>Save and resume</h2><p>Source: ${report.resources.length} resources. Target: ${targetRaw?.items.length||0} resources. ${Object.keys(securityDecisions).length} security mappings.</p><div class="toolbar"><button data-action="projectsave" ${projectLoading?'disabled':''}>↓ Save project JSON</button><button class="secondary" data-action="projectopen" ${projectLoading?'disabled':''}>Open project JSON</button></div><p>Opening a valid project replaces this tab’s workspace. Save current work before opening another project. Invalid files leave the current workspace intact.</p><div class="notice">Project files contain sanitized inventory, configuration references, notes and evidence metadata. Arbitrary annotations/commands or notes may still contain sensitive information. Review before sharing. Files are not encrypted and are not uploaded by the app.</div></section><section class="panel"><h2>Consolidated migration bundle</h2><p>One ZIP with project JSON, source/target inventories, assessment and migration plan, image plan and runner, security plan/evidence template, stateful runbook, target preflight runner, GitOps handoff, collector and the currently selected pilot/routing drafts with dry-run scripts.</p><p>Pilot: ${esc(pilotChoice||'Not selected — open Stateless pilot first')}.<br>Routing: ${esc(routeChoice||'Not selected — open Ingress & gateways first')}.</p><button data-action="projectbundle" ${bundleBusy||projectLoading?'disabled':''}>${bundleBusy?'Preparing bundle…':'↓ Export migration ZIP'}</button><p>Only saved form settings are exported; use each section’s Update/Save button before exporting. Blockers and unverified evidence remain visible in the bundle. No runner or script is executed.</p></section></div><div class="error" role="alert">${esc(projectError)}</div>${handoffWorkbench()}${projectWarnings.length?`<section class="panel"><h2>Restored evidence notes</h2>${projectWarnings.map(w=>`<p>${esc(w)}</p>`).join('')}<p>Findings and drafts are recomputed from the restored data. Saved readiness flags are never trusted; the production gate stays closed.</p></section>`:''}`;}
async function exportProjectBundle(){if(bundleBusy)return;bundleBusy=true;projectError='';if(view==='project')render();try{const snapshot=projectSnapshot(),handoff=handoffReview(),json=x=>JSON.stringify(x,null,2),files=[{name:'handoff/migration-action-checklist.json',body:json(H.checklist(handoff))},{name:'handoff/pilot-handoff.json',body:json(handoff)},{name:'handoff/pilot-handoff.md',body:H.markdown(handoff)},{name:'pilot-execution/pilot-execution-draft.json',body:json(executionPlan().preflight.manifests)},{name:'pilot-execution/execution-plan.json',body:json(executionPlan())},{name:'pilot-execution/README.md',body:X.readme(executionPlan())},{name:'pilot-execution/RECOVERY.md',body:X.recovery},{name:'waves/wave-plan.json',body:json(wavePlan())},{name:'waves/wave-runbook.md',body:Q.markdown(wavePlan())},{name:'acceptance/acceptance-plan.json',body:json(acceptancePlan())},{name:'acceptance/acceptance-evidence-template.json',body:json(A.template(acceptancePlan()))},{name:'acceptance/acceptance-review.json',body:json({plan:acceptancePlan(),evidence:acceptanceEvidence,summary:acceptanceSummary()})},{name:'acceptance/acceptance-workbook.md',body:A.markdown(acceptancePlan(),acceptanceEvidence)},{name:'migration-journey.json',body:json(journeySummary())},{name:'project.vks-project.json',body:json(snapshot)},{name:'inventory/source.json',body:json(snapshot.state.source)},{name:'assessment.json',body:json({...report,targetComparison:comparison(),migrationPlan:migrationPlan(),productionReady:false})},{name:'migration-plan.md',body:planText()},{name:'security/security-plan.json',body:json(securityPlan())},{name:'security/security-evidence-template.json',body:json(S.template(securityPlan()))},{name:'security/security-summary.json',body:json(securitySummary())},{name:'images/image-plan.json',body:json(imagePlan())},{name:'target/target-plan.json',body:json(targetCheckPlan())},{name:'target/target-preflight-review.json',body:json({summary:C.summary(targetCheckPlan(),targetCheckEvidence),evidence:targetCheckEvidence})},{name:'stateful/stateful-plan.json',body:json(storagePlan())},{name:'stateful/stateful-runbook.md',body:T.markdown(storagePlan())}];
 files.push({name:'pilot-execution/pilot-timeline.json',body:json(pilotTimeline())});if(executionObservation)files.push({name:'pilot-execution/pilot-observation.json',body:json(executionObservation)});if(executionInspection)files.push({name:'pilot-execution/pilot-inspection.json',body:json(executionInspection)});if(executionCleanup)files.push({name:'pilot-execution/pilot-cleanup.json',body:json(executionCleanup)});if(executionEvidence)files.push({name:'pilot-execution/pilot-run.json',body:json(executionEvidence)});if(lastChangeReview)files.push({name:'inventory/adopted-change-review.json',body:json(lastChangeReview)});if(snapshot.state.target)files.push({name:'inventory/target.json',body:json(snapshot.state.target)});if(securityEvidence)files.push({name:'security/security-evidence.json',body:json(securityEvidence)});if(imageEvidence)files.push({name:'images/image-evidence.json',body:json(imageEvidence)});
 if(pilotChoice){const b=pilotBundle();files.push({name:'pilot/pilot-draft.json',body:json(b.manifests)},{name:'pilot/pilot-review.json',body:json(b)},{name:'pilot/validate-pilot.sh',body:B.validationScript(b)});}if(routeChoice){const b=routingBundle();files.push({name:'routing/routing-draft.json',body:json(b.manifests)},{name:'routing/routing-review.json',body:json(b)},{name:'routing/validate-routing.sh',body:B.validationScript(b).replaceAll('pilot-draft.json','routing-draft.json').replaceAll('pilot-review.json','routing-review.json').replaceAll('validate-pilot.sh','validate-routing.sh')});}
 for(const file of gitopsBundle().files)files.push({name:'gitops/'+file.name,body:file.body});
 const assets=await Promise.allSettled([fetch('pilot-runner.py').then(async r=>{if(!r.ok)throw Error('Pilot runner download failed');return {name:'pilot-execution/pilot-runner.py',body:await r.text()};}),fetch('target-preflight.py').then(async r=>{if(!r.ok)throw Error('Pilot preflight helper download failed');return {name:'pilot-execution/target-preflight.py',body:await r.text()};}),fetch('collect.py').then(async r=>{if(!r.ok)throw Error('Collector download failed');return {name:'collector/collect.py',body:await r.text()};}),fetch('target-preflight.py').then(async r=>{if(!r.ok)throw Error('Target runner download failed');return {name:'target/target-preflight.py',body:await r.text()};}),fetch('image-runner.py').then(async r=>{if(!r.ok)throw Error('Image runner download failed');return {name:'images/image-runner.py',body:await r.text()};})]);for(const result of assets){if(result.status!=='fulfilled')throw result.reason;files.push(result.value);}
 files.push({name:'README.md',body:'# VKS migration review bundle\n\nProject: '+snapshot.name+'\nSaved: '+snapshot.savedAt+'\nProduction gate: CLOSED. This archive is a review package, not an execution approval.\n\nStart with handoff/pilot-handoff.md for the current gaps and next owner review. Open project.vks-project.json in Project & bundle to resume. Assessment and drafts are recomputed. Review source and target evidence age before proceeding.\n\nInventory data is sanitized, not guaranteed free of sensitive annotations/commands. Review files before sharing. Credentials and secret values must come from approved external providers.\n\nImage plan: review images/image-plan.json, authenticate locally with Skopeo, then from the images directory run python3 image-runner.py --plan image-plan.json --output image-results.json. Default mode verifies only. Explicit --copy writes destination tags and may overwrite them. Invalid image plans stop the runner. No source image is deleted.\n\nSelected pilot: '+(snapshot.state.pilot.choice||'NONE — select one in the app and export again')+'\nSelected routing object: '+(snapshot.state.routing.choice||'NONE — select one in the app and export again')+'\n\nFor selected drafts, review their *-review.json file. From the pilot or routing directory run the corresponding validate-*.sh script with an explicit TARGET_CONTEXT. Scripts stop on known blockers and otherwise run server dry-run and diff only. They do not deploy.\n\nSecurity records are external reports only. Define and run actual source/target cases using the evidence template; import completed evidence into the app. Confirm allowed and denied behavior, exemptions, controller health and coverage. The production gate cannot open automatically.\n\nTarget preflight: from target/ run python3 target-preflight.py --context TARGET_CONTEXT --plan target-plan.json --output target-results.json. This performs reads and non-persisted server dry-run only; import observations in Target preflight. See stateful/stateful-plan.json and stateful/stateful-runbook.md for recorded data-transfer strategies, RPO/RTO inputs, consistency groups and failback checkpoints. These are unverified planning inputs; no data-transfer tool ran. DNS/certificate changes, application/data migration, acceptance, cutover and recovery need separate reviewed procedures. No action ran when exporting or opening this bundle.\n'});
 download('vks-migration-bundle.zip',J.zip(files),'application/zip');projectSavedAt=snapshot.savedAt;toast('Migration ZIP exported; production gate remains closed');}catch(error){projectError=error.message;}finally{bundleBusy=false;if(view==='project')render();}}
function securityWorkbench(){const p=securityPlan(),g=S.summary(p,securityEvidence),targets=(targetRaw?.items||[]).filter(r=>S.catalog({items:[r]}).length);if(!p.controls.some(c=>c.id===securityChoice))securityChoice=p.controls[0]?.id||'';const c=p.controls.find(c=>c.id===securityChoice),d=securityDecisions[securityChoice]||{};
 return `<div class="banner"><div><strong>Security parity gate · Closed</strong><p>${esc(g.reason)} Changes to inventory, mappings or scenarios invalidate previous evidence. The app does not install policies or execute security tests.</p></div>${badge('Owner review required')}</div><div class="stats"><div class="stat"><small>Required controls observed</small><strong>${g.total}</strong><div class="sub">Not an exhaustive control inventory</div></div><div class="stat"><small>Reported cases complete</small><strong>${g.reportedComplete}</strong><div class="sub">External reports; independent review required</div></div><div class="stat danger"><small>Controls unresolved</small><strong>${g.unresolved}</strong><div class="sub">Mapping, scenario or evidence gaps</div></div><div class="stat"><small>Coverage</small><strong>Partial</strong><div class="sub">Unknown controls remain possible</div></div></div><section class="panel"><h2>1. Inventory controls and dependencies</h2><p>OPA/Gatekeeper, Kyverno, NetworkPolicy, PSA, RBAC, identity, secret providers, mesh, admission webhooks and secondary networking are inventoried when present. Policy existence does not prove effective enforcement.</p><div class="tablewrap"><table><thead><tr><th>Control</th><th>Family / observed mode</th><th>Mapping</th><th>Evidence</th></tr></thead><tbody>${p.controls.map(x=>`<tr><td><button class="pill" data-security-control="${esc(x.id)}">${esc(x.id)}</button></td><td>${esc(x.family)}<small>${esc(x.enforcement)}</small></td><td>${esc(x.action)}<small>${esc(x.targetRef||'No target mapping')}</small></td><td>${esc(g.controls.find(y=>y.id===x.id).status)}</td></tr>`).join('')||'<tr><td colspan="4">No known controls observed. Coverage is incomplete; this is not evidence of no enforcement.</td></tr>'}</tbody></table></div></section>${c?`<section class="panel"><h2>2. Map a required control</h2><p class="mono">${esc(c.id)}</p><p>${esc(c.family)} · Source mode: ${esc(c.enforcement)}. Target resources in the list are observed objects, not certified equivalent controls.</p><button class="pill" data-resource="${esc(c.id)}">Inspect source object</button><form id="securityForm"><div class="formgrid"><label>Migration action<select name="action">${['Unmapped','Retain','Replace','Manual adaptation'].map(x=>`<option ${d.action===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Observed target resource ID<input name="targetRef" value="${esc(d.targetRef||'')}" list="securityTargets" placeholder="namespace/Kind/name" required><datalist id="securityTargets">${targets.map(x=>`<option value="${esc(E.id(x))}">`).join('')}</datalist></label><label>Mapping rationale<textarea name="rationale" required rows="3">${esc(d.rationale||'')}</textarea></label><label>Expected violation behavior<select name="violationExpected">${(c.expected==='Define'?['Define',...S.OUTCOMES]:[c.expected]).map(x=>`<option ${x===(d.violationExpected||c.tests[1].expected)?'selected':''}>${x}</option>`).join('')}</select></label><label>Positive / permitted scenario<textarea name="allowScenario" required rows="3" placeholder="Identify identities, namespaces, labels, request and expected allowed behavior">${esc(d.allowScenario||'')}</textarea></label><label>Violation / excluded scenario<textarea name="violationScenario" required rows="3" placeholder="Define a denied request, warning/audit test, or dependency review as appropriate">${esc(d.violationScenario||'')}</textarea></label></div><p>Source and target run the same defined scenarios. Gatekeeper audit/warn modes retain their distinct expected outcomes. Definitions/templates use documented review cases. Infrastructure errors and timeouts are not policy denials.</p><button type="submit">Save mapping & scenarios</button></form></section>`:''}<section class="panel"><h2>3. Export the plan and evidence template</h2><p>Plan revision: <span class="mono">${esc(p.planRevision)}</span>. Define all cases before testing. Run approved tests externally and provide reviewable log/artifact references. Template records begin as NotRun; importing the blank template cannot satisfy a case.</p><div class="toolbar"><button data-action="securityplan">↓ security-plan.json</button><button class="secondary" data-action="securitytemplate">↓ security-evidence-template.json</button><button class="secondary" data-action="securityexport">↓ security-review.json</button></div><div class="notice">Standard NetworkPolicy is additive and depends on CNI enforcement. This release does not translate Calico/Antrea/Cilium policy semantics, Rego/CEL, secondary-network isolation or enterprise identity automatically.</div></section><section class="panel"><div class="panelhead"><h2>4. Import source and target test records</h2><button data-action="securityimport">Import evidence JSON</button></div><div class="error" role="alert">${esc(securityError)}</div>${securityEvidence?`<p>${esc(securityEvidence.note)}</p><div class="tablewrap"><table><thead><tr><th>Control / case</th><th>Side / context</th><th>Outcome</th><th>Record status</th><th>Evidence reference</th></tr></thead><tbody>${securityEvidence.results.map(r=>`<tr><td class="mono">${esc(r.controlId)}<small>${esc(r.caseId)}</small></td><td>${esc(r.side)}<small>${esc(r.context)}</small></td><td>${esc(r.outcome)}</td><td>${esc(r.status)}</td><td>${esc(r.evidenceRef)}<small>${esc(r.observedAt||'No timestamp')}</small></td></tr>`).join('')}</tbody></table></div>`:'<p>No test records imported. Allowed and violation cases on distinct source and target contexts remain unverified.</p>'}<div class="notice">The production gate stays closed even if every reported case matches. Close collection gaps, review effective permissions/policy order/exemptions, and obtain independent security and application acceptance.</div><a href="https://kubernetes.io/docs/concepts/services-networking/network-policies/" target="_blank" rel="noopener" class="textlink">Kubernetes NetworkPolicy behavior ↗</a></section>`;
}
function routing(){const choices=R.candidates(raw);if(!choices.length)return '<section class="panel"><h2>No source Ingress resources</h2><p>This workbench supports networking.k8s.io/v1 Ingress → Ingress or HTTPRoute drafts. Existing HTTPRoutes, service-mesh routes and proprietary API gateway CRs require separate adapters.</p></section>';
 if(!choices.some(x=>x.id===routeChoice)){routeChoice=choices.find(x=>x.name==='web-pilot')?.id||choices[0].id;}
 const selected=report.resources.find(x=>E.id(x)===routeChoice),b=routingBundle(),observed=(targetRaw?.items||[]),gateways=observed.filter(x=>x.kind==='Gateway'),classes=observed.filter(x=>x.kind==='IngressClass');
 return `<div class="banner"><div><strong>Preserve routing intent before shifting traffic</strong><p>Scope: standard v1 Ingress rules to a mapped IngressClass or HTTPRoutes attached to an existing Gateway listener. WAF, auth, custom gateway plugins and controller annotations need implementation-specific mapping.</p></div>${badge('Draft only')}</div><section class="panel"><h2>1. Source routing object</h2><select id="routeSource" aria-label="Source Ingress">${choices.map(x=>`<option value="${esc(x.id)}" ${x.id===routeChoice?'selected':''}>${esc(x.namespace+'/'+x.name)}</option>`).join('')}</select><p>Destination namespace is preserved: <b>${esc(selected.metadata.namespace||'default')}</b>. Source routing stays untouched.</p><form id="routingForm"><h3>2. Destination mapping</h3><div class="formgrid"><label>Output API<select id="routeMode" name="mode">${['Ingress','HTTPRoute'].map(x=>`<option ${routeMode===x?'selected':''}>${x}</option>`).join('')}</select></label>${routeMode==='Ingress'?`<label>Destination IngressClass<input name="ingressClass" value="${esc(routeClass)}" list="routeClasses" placeholder="Explicit class name" required><datalist id="routeClasses">${classes.map(x=>`<option value="${esc(x.metadata.name)}">`).join('')}</datalist></label>`:`<label>Existing Gateway name<input name="gateway" value="${esc(routeGateway)}" placeholder="Gateway name" required></label><label>Gateway namespace<input name="gatewayNamespace" value="${esc(routeGatewayNS||selected.metadata.namespace||'default')}" required></label><label>Listener section name<input name="listener" value="${esc(routeListener)}" placeholder="e.g. https" required></label>`}</div><p>${routeMode==='Ingress'?classes.length+' IngressClass object(s) observed in target inventory. Names are evidence of presence only.':gateways.length+' Gateway object(s) observed. This draft never creates or changes a shared Gateway.'}</p><button type="submit">Update route preview</button></form>${gateways.length?`<details><summary>Observed target Gateways and listeners</summary>${gateways.map(g=>`<div class="workitem"><b class="mono">${esc((g.metadata.namespace||'default')+'/'+g.metadata.name)}</b><p>Class: ${esc(g.spec?.gatewayClassName||'Unspecified')}</p>${(g.spec?.listeners||[]).map(l=>`<p class="mono">${esc(l.name)} · ${esc(l.protocol)}:${esc(l.port)} · ${esc(l.hostname||'Any hostname')} · namespace rule ${esc(l.allowedRoutes?.namespaces?.from||'Same')}</p>`).join('')}</div>`).join('')}</details>`:''}<a href="#compare" class="textlink">Import or review target inventory →</a></section><section class="panel"><div class="panelhead"><h2>3. Routing transformation preview</h2>${badge(b.blockers.length?'Blocker':'Unverified')}</div><p>${esc(b.status)} · ${b.manifests.items.length} resource(s) · ${b.tests.length} route test case(s)</p>${b.blockers.length?`<div class="notice"><b>Resolve ${b.blockers.length} blocker(s) before validation</b>${b.blockers.map(x=>`<p>${esc(x.reason)}</p>`).join('')}</div>`:''}<div class="tablewrap"><table><thead><tr><th>Field</th><th>Source behavior</th><th>Draft behavior</th></tr></thead><tbody>${b.changes.map(x=>`<tr><td class="mono">${esc(x.path)}</td><td>${esc(x.before)}</td><td>${esc(x.after)}</td></tr>`).join('')}</tbody></table></div><details><summary>Generated routing manifest (JSON)</summary><pre>${esc(JSON.stringify(b.manifests,null,2))}</pre></details><h3>Behavioral test cases · not run</h3><div class="tablewrap"><table><thead><tr><th>Hostname</th><th>Path / match</th><th>Expected backend</th><th>Status</th></tr></thead><tbody>${b.tests.map(t=>`<tr><td>${esc(t.host)}</td><td class="mono">${esc(t.path)}<small>${esc(t.match)}</small></td><td class="mono">${esc(t.expectedBackend)}</td><td>${esc(t.status)}</td></tr>`).join('')||'<tr><td colspan="4">No rule-derived test cases. Review default routing manually.</td></tr>'}</tbody></table></div><h3>Required prerequisites</h3>${b.prerequisites.map(x=>`<div class="workitem"><b>${esc(x.resource)}</b><p>${esc(x.action)}</p></div>`).join('')}</section><section class="panel"><h2>4. Download routing review files</h2><div class="toolbar"><button data-action="routemanifest">↓ routing-draft.json</button><button class="secondary" data-action="routereview">↓ routing-review.json</button><button class="secondary" data-action="routevalidate">↓ validate-routing.sh</button></div><pre>bash validate-routing.sh TARGET_CONTEXT</pre><p>The script stops on known blockers. Otherwise it runs only server dry-run and diff against an explicit context. It cannot prove route acceptance, backend reachability or security parity.</p><div class="notice">DNS, certificates, load-balancer addresses, source routes and Gateway listeners are never modified by this app. Deployment and cutover remain separate actions after review and testing.</div><a class="textlink" href="https://gateway-api.sigs.k8s.io/guides/getting-started/migrating-from-ingress/" target="_blank" rel="noopener">Kubernetes Gateway API migration guide ↗</a></section>`;
}
function images(){const p=imagePlan();return `<div class="banner"><div><strong>Registry plan → local runner → reported evidence</strong><p>No registry connection is made by this app. Authenticate locally with Skopeo, review destination tags, then run the exported plan. “Migrate” keeps the source images; source deletion is not implemented.</p></div>${badge('Not executed by app')}</div><section class="panel"><h2>1. Choose registry strategy</h2><form id="imageForm"><div class="formgrid"><label>Image strategy<select name="policy">${['Reuse registry','Mirror to Harbor','Migrate to Harbor'].map(x=>`<option ${imageStrategy===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Destination registry / project<input name="prefix" value="${esc(imagePrefix)}" placeholder="harbor.example.com/migrated"></label></div><p>The destination path includes the source registry and repository to reduce name collisions. The example Harbor address must be replaced for a real migration.</p><div class="tablewrap"><table><thead><tr><th>Source image / workloads</th><th>Planned destination</th><th>Optional explicit destination override</th></tr></thead><tbody>${p.rows.map((r,i)=>`<tr><td class="mono">${esc(r.source)}<small>${r.workloads.map(esc).join('<br>')}</small></td><td class="mono">${esc(r.destination)}<small>${esc(r.operation)} · ${r.sourcePinned?'Source digest pinned':'Source tag resolved at runtime'}</small></td><td><input name="override-${i}" data-image-source="${esc(r.source)}" value="${esc(imageOverrides[r.source]||'')}" placeholder="Use suggested destination" aria-label="Destination override for ${esc(r.source)}"></td></tr>`).join('')}</tbody></table></div><button type="submit">Update image plan</button></form>${p.errors.length?`<div class="error" role="alert">${p.errors.map(esc).join('<br>')}</div>`:''}</section><section class="panel"><h2>2. Export and run locally</h2><p>Requires Python 3 and Skopeo. Keep image-plan.json and image-runner.py together. Use local credential helpers / skopeo login; credentials are never entered in this app.</p><div class="toolbar"><button data-action="imageplan" ${p.errors.length?'disabled':''}>↓ image-plan.json</button><a href="image-runner.py" download class="button secondary">↓ image-runner.py</a><button class="secondary" data-action="imagecommands" ${p.errors.length?'disabled':''}>↓ Copy command preview</button></div><pre># Read-only registry verification
python3 image-runner.py --plan image-plan.json --output image-results.json

# Explicit registry writes: destination tags may be overwritten
python3 image-runner.py --plan image-plan.json --copy --output image-copy-results.json</pre><p>Copy mode resolves the source manifest digest and copies that immutable reference with all platforms and digest preservation. TLS verification and Skopeo trust settings remain enabled. Output files are created exclusively and cannot overwrite previous reports.</p><div class="notice">${esc(p.verificationScope)} Copying does not retire the source registry or transfer cloud identity.</div><a class="textlink" href="https://github.com/podman-container-tools/skopeo/blob/main/docs/skopeo-copy.1.md" target="_blank" rel="noopener">Skopeo copy documentation ↗</a></section><section class="panel"><div class="panelhead"><h2>3. Import runner results</h2><button data-action="imageresults" ${p.errors.length?'disabled':''}>Import results JSON</button></div><div class="error" role="alert">${esc(imageError)}</div>${imageEvidence?`<p>${esc(imageEvidence.note)}</p><div class="tablewrap"><table><thead><tr><th>Source → destination</th><th>Reported result</th><th>Manifest digest</th></tr></thead><tbody>${imageEvidence.results.map(r=>`<tr><td class="mono">${esc(r.source)}<small>→ ${esc(r.destination)}</small></td><td>${badge(r.status==='Reported digest match'?'Observed':'Unknown')}<small>${esc(r.status)}</small></td><td class="mono">${esc(r.sourceDigest||'Not reported')}<small>Destination: ${esc(r.destinationDigest||'Not reported')}</small></td></tr>`).join('')}</tbody></table></div>`:'<p>No results imported. Every image remains unchecked. Imported matching results describe registry manifest content; they are not an authenticated attestation or a target-node pull test.</p>'}</section><section class="panel"><h2>4. Supply pilot image references</h2><p>Use planned destinations for a draft, or digest pins from matching reported results. This updates image mappings across pilot selections. Per-pilot manual overrides take precedence. Image access prerequisites remain unverified.</p><div class="toolbar"><button class="secondary" data-action="imageuseplanned" ${p.errors.length?'disabled':''}>Use planned destinations</button><button data-action="imageusepins" ${!imageEvidence?.results.some(r=>r.pinnedDestination)?'disabled':''}>Use reported digest pins</button><a class="textlink" href="#pilot">Open Stateless pilot →</a></div><p>${Object.keys(imagePilotRefs).length} image reference(s) supplied to the pilot builder.</p></section>`;}
function imageCommands(){const p=imagePlan(),q=x=>"'"+x.replace(/'/g,"'\\''")+"'";return '# Reviewed command preview only. Tags may change: prefer the runner, which resolves and copies immutable source digests.\n# Commands are not executed by the app. Registry credentials stay local.\n\n'+p.rows.map(r=>r.operation==='Copy'?`# ${r.source}\nskopeo copy --all --preserve-digests ${q('docker://'+r.sourceCanonical)} ${q('docker://'+r.destination)}`:`skopeo inspect --raw ${q('docker://'+r.sourceCanonical)}`).join('\n\n')+'\n';}
function pilotTimeline(){return X.timeline(executionPlan(),executionEvidence,executionHistory,executionInspection,executionCleanup);}
function timelineWorkbench(){const t=pilotTimeline();return `<section class="panel"><div class="panelhead"><div><h2>Pilot run timeline</h2><p>${t.history.records.length} retained observations · ${esc(t.runId||'No run imported')}</p></div><button class="secondary" data-action="executiontimeline">↓ Export timeline JSON</button></div><p>Deployment or validation, repeated observations, and the latest linked inspection and cleanup for this run. Times are reported by imported receipts; this is not live monitoring.</p>${t.history.truncated?'<div class="notice">History limit reached: only the most recent 50 observations are retained. Earlier imported observations may be omitted. Keep previous project exports for the complete review.</div>':''}${t.events.length?`<div class="tablewrap"><table><thead><tr><th>Reported time (UTC)</th><th>Record</th><th>Result</th><th>Observed checks and changes</th></tr></thead><tbody>${t.events.map(e=>{const r=e.record;return `<tr><td class="mono">${esc(new Date(r.observedAt).toISOString())}</td><td>${esc(e.type)}</td><td>${esc(r.status)}</td><td>${r.rollout?`Rollout ${esc(r.rollout.status)} · HTTP ${esc(r.smoke.status)} · ${r.images.length} container observations`:`${r.rows.length} roots · ${r.actions.length} cleanup requests`}${e.changes?`<small>${e.changes.map(esc).join(' · ')}</small><details><summary>Observation details</summary><p>${esc(r.rollout.detail)} ${esc(r.smoke.detail)}</p>${r.images.map(i=>`<p class="mono">${esc(i.pod+'/'+i.container)} · ${i.ready?'Ready':'Unresolved'} · ${esc(i.reason)}<small>${esc(i.imageID||'No runtime image ID')}</small></p>`).join('')}</details>`:''}${r.error?`<small>${esc(r.error)}</small>`:''}</td></tr>`;}).join('')}</tbody></table></div>`:'<p>Import the original run receipt, then individual observation or recovery receipts to start this timeline.</p>'}<p>Exact duplicate observations are ignored. History belongs to the current plan and run; importing a changed original run receipt or changing scope clears it. Reimporting the identical original receipt preserves history. Save a project before switching runs. Production gate remains closed.</p></section>`;}
function observationWorkbench(){const state=X.lifecycle(executionPlan(),executionEvidence,executionObservation,executionInspection,executionCleanup);return `<section class="panel"><div class="panelhead"><div><h2>Observe an existing pilot</h2><p>${esc(state.status)} · production gate closed</p></div><button class="secondary" data-action="executionimport">Import run / observation receipt</button></div><p>${esc(state.detail)}</p><p>Use the original bound plan/package and deploy receipt. This command checks current cluster and root object identities, then refreshes rollout, owned container image/startup observations and the approved loopback HTTP GET. It creates, updates and deletes no Kubernetes resources. Partial, absent, replaced or terminating roots need recovery inspection first.</p><pre>python3 pilot-runner.py observe --context TARGET --receipt pilot-run.json --output pilot-observation.json</pre><p>Choose a new output filename each time. Import the original deploy receipt first, then its observation. Older observations enter the timeline without replacing newer state. At identical timestamps, unresolved observations take precedence. The most recent 50 observations are retained; export and save the project to preserve your review. The approved HTTP path is repeated; Service/Ingress paths and security enforcement remain separate tests. Results are historical snapshots, not background monitoring.</p>${executionObservation?`<h3>Observation · ${esc(executionObservation.status)}</h3><p>${esc(executionObservation.observedAt)} · reported root identity ${executionObservation.identityMatched?'matched':'unresolved'} · rollout ${esc(executionObservation.rollout.status)} · HTTP smoke ${esc(executionObservation.smoke.status)}</p><p>${esc(executionObservation.smoke.detail)} ${esc(executionObservation.error)}</p><div class="tablewrap"><table><thead><tr><th>Pod / container</th><th>Startup</th><th>Runtime image ID</th></tr></thead><tbody>${executionObservation.images.map(r=>`<tr><td>${esc(r.pod+'/'+r.container)}</td><td>${r.ready?'Ready':'Unresolved'}<small>${esc(r.reason)}</small></td><td class="mono">${esc(r.imageID||'Not observed')}</td></tr>`).join('')}</tbody></table></div><p>${esc(executionObservation.note)}</p>`:'<p>No refreshed observation imported for this pilot run.</p>'}</section>`;}
function recoveryWorkbench(){const rowTable=r=>`<div class="tablewrap"><table><thead><tr><th>Resource</th><th>Observed state</th><th>UID / resource version</th><th>Review</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td>${esc(x.namespace+'/'+x.kind+'/'+x.name)}</td><td>${esc(x.state)}</td><td class="mono">${esc(x.uid||'Not observed')}<small>${esc(x.resourceVersion||'')}</small></td><td>${esc(x.detail)}</td></tr>`).join('')}</tbody></table></div>`;return `<section class="panel"><div class="panelhead"><div><h2>6. Inspect and recover this pilot run</h2><p>Read-only inspection first; cleanup is a separate local command.</p></div><button class="secondary" data-action="executionimport">Import run / inspection / cleanup receipt</button></div><p>Use the original deploy receipt and bound execution plan. Save its matching project before changing the workspace. For an older package, download the updated runner and helper alongside its original plan and receipt. Inspection reports current UID, resource version, run label and run-labeled Pods/ReplicaSets. Cleanup requires an unblocked inspection less than ten minutes old, the exact run ID and acknowledgment of owner-reviewed writer fencing and external-state recovery.</p><pre>python3 pilot-runner.py inspect --context TARGET --receipt pilot-run.json --output pilot-inspection.json

# Only after inspecting the resources and reviewing external state:
python3 pilot-runner.py cleanup --context TARGET --receipt pilot-run.json --inspection pilot-inspection.json --confirm-run ${esc(executionEvidence?.mode==='deploy'?executionEvidence.runId:'RUN_ID')} --ack-external-state --output pilot-cleanup.json</pre><div class="toolbar"><a href="pilot-runner.py" download class="textlink">↓ Updated pilot runner</a><a href="target-preflight.py" download class="textlink">↓ Matching preflight helper</a></div><p>The cleanup command verifies all root objects before requesting deletion, then rechecks each object and sends UID plus resourceVersion preconditions. Services are requested first, then the Deployment with normal foreground garbage collection. A changed object blocks further requests. Explicit requests target only the inspected Deployment and Services; normal Kubernetes garbage collection can remove their dependents. Review owner relationships before cleanup. No force, grace-period override, finalizer removal or explicit namespace/shared-reference deletion is provided. Earlier requests may already have succeeded when a later one fails.</p><div class="notice">Deletion requested is not deletion completed. Re-run inspect using a new output filename to verify scoped absence. Run-labeled Pods/ReplicaSets can remain while garbage collection completes. This does not verify external data reconciliation, hidden side effects or production acceptance.</div>${executionInspection?`<h3>Inspection · ${esc(executionInspection.status)}</h3><p>${esc(executionInspection.observedAt)} · ${executionInspection.dependents.length} run-labeled Pods/ReplicaSets observed</p>${rowTable(executionInspection)}<p class="error">${esc(executionInspection.error)}</p>`:'<p>Import a deploy receipt, then its inspection receipt to review recovery scope here.</p>'}${executionCleanup?`<h3>Cleanup · ${esc(executionCleanup.status)}</h3><p>${esc(executionCleanup.observedAt)} · ${executionCleanup.actions.filter(x=>x.outcome==='Requested').length} acknowledged delete requests · ${executionCleanup.dependents.length} run-labeled Pods/ReplicaSets still observed</p>${rowTable(executionCleanup)}<div class="tablewrap"><table><thead><tr><th>Delete request</th><th>UID precondition</th><th>Reported outcome</th></tr></thead><tbody>${executionCleanup.actions.map(x=>`<tr><td>${esc(x.namespace+'/'+x.kind+'/'+x.name)}</td><td class="mono">${esc(x.uid)}</td><td>${esc(x.outcome)}</td></tr>`).join('')}</tbody></table></div><p class="error">${esc(executionCleanup.error)}</p><p>${esc(executionCleanup.note)}</p>`:''}</section>`;}
function executionWorkbench(){const p=executionPlan();return `<section class="panel"><div class="panelhead"><div><h2>5. Run an isolated pilot locally</h2><p>One replica · create-only Deployment and up to ten ClusterIP Services · no source, Ingress or DNS changes</p></div>${badge(p.blockers.length?'Blocked':'Requires local approval')}</div><p>Prepare the namespace, referenced configuration, approved security controls, non-production dependency access and recovery procedure. Configure the explicit context in <a href="#target">Target preflight</a> and import source/target snapshots containing kube-system UIDs. Every container needs a sha256 digest pin.</p><form id="executionForm"><div class="formgrid"><label>Approved Pod HTTP smoke port<input name="smokePort" type="number" min="1" max="65535" value="${p.settings.smokePort}" required></label><label>Read-only HTTP smoke path<input name="smokePath" maxlength="500" value="${esc(p.settings.smokePath)}" required></label><label>Expected HTTP status<input name="expectedStatus" type="number" min="200" max="499" value="${p.settings.expectedStatus}" required></label><label>Maximum HTTP latency (ms)<input name="maxLatencyMs" type="number" min="1" max="15000" value="${p.settings.maxLatencyMs}" required></label><label>Optional response marker (no secrets)<input name="smokeMarker" maxlength="200" value="${esc(p.settings.smokeMarker)}"></label><label>Rollout timeout (seconds)<input name="rolloutSeconds" type="number" min="30" max="900" value="${p.settings.rolloutSeconds}" required></label></div><button type="submit">Save local pilot settings</button></form>${p.blockers.length?`<div class="notice"><b>${p.blockers.length} execution blocker(s)</b>${p.blockers.map(x=>`<p>${esc(x.reason)}</p>`).join('')}</div>`:'<p>No generated execution blockers. Prerequisites and owner authorization remain required.</p>'}<details><summary>Review the execution plan (one replica; run selectors are refined locally)</summary><pre>${esc(JSON.stringify(p,null,2))}</pre></details><div class="toolbar"><button data-action="executionzip" ${executionBusy?'disabled':''}>${executionBusy?'Preparing package…':'↓ Runnable pilot package'}</button><button class="secondary" data-action="executionimport">Import pilot result</button></div><pre>python3 pilot-runner.py validate --context TARGET --output pilot-validation.json

python3 pilot-runner.py deploy --context TARGET --validation pilot-validation.json \
  --confirm-workload ${esc(p.workload||'WORKLOAD_ID')} --ack-prerequisites --output pilot-run.json</pre><p>Replace TARGET with the configured context. Deploy requires a passing validation from this plan/context within 30 minutes and repeats live checks. It refuses name conflicts and observed target selector overlap. Runtime run labels refine the Deployment and Service selectors. Output receipts are exclusive, private files and record each created UID; interrupted or failed creates need recovery review. No automatic rollback or deletion occurs.</p><div class="notice">The HTTP GET uses a loopback-only port-forward to an owned Pod. It does not exercise Service, Ingress or network-policy paths. Redirects and proxies are disabled, and response bodies are omitted. Runtime image IDs are observations, not proof that a multi-platform registry digest equals a node image ID. The production gate remains closed.</div>${executionEvidence?`<h3>Imported ${esc(executionEvidence.mode)} result · ${esc(executionEvidence.status)}</h3><p>${esc(executionEvidence.context)} · ${esc(executionEvidence.observedAt)} · ${executionEvidence.created.length} recorded creates · ${executionEvidence.uncertain.length} uncertain response(s)</p><p>Rollout: ${esc(executionEvidence.rollout.status)} · HTTP smoke: ${esc(executionEvidence.smoke.status)}</p><p>${esc(executionEvidence.smoke.detail)} ${esc(executionEvidence.error)}</p><div class="tablewrap"><table><thead><tr><th>Created resource</th><th>Recorded UID</th></tr></thead><tbody>${executionEvidence.created.map(r=>`<tr><td>${esc(r.namespace+'/'+r.kind+'/'+r.name)}</td><td class="mono">${esc(r.uid)}</td></tr>`).join('')}</tbody></table><table><thead><tr><th>Pod / container</th><th>Reported image</th><th>Runtime image ID</th></tr></thead><tbody>${executionEvidence.images.map(r=>`<tr><td>${esc(r.pod+'/'+r.container)}<small>${r.ready?'Ready':'Unresolved'} ${esc(r.reason)}</small></td><td class="mono">${esc(r.image)}</td><td class="mono">${esc(r.imageID)}</td></tr>`).join('')}</tbody></table></div><p>${esc(executionEvidence.note)}</p>`:'<p>No local pilot execution result imported. Exporting a package runs nothing.</p>'}<a href="#acceptance" class="textlink">Review source/target application acceptance →</a></section>`;}
async function exportExecutionPackage(){if(executionBusy)return;executionBusy=true;executionError='';render();try{const p=executionPlan(),results=await Promise.allSettled(['pilot-runner.py','target-preflight.py'].map(async name=>{const r=await fetch(name);if(!r.ok)throw Error('Pilot package asset download failed');return {name,body:await r.text()};})),files=[{name:'pilot-execution-draft.json',body:JSON.stringify(p.preflight.manifests,null,2)},{name:'execution-plan.json',body:JSON.stringify(p,null,2)},{name:'README.md',body:X.readme(p)},{name:'RECOVERY.md',body:X.recovery}];for(const r of results){if(r.status!=='fulfilled')throw r.reason;files.push(r.value);}download('vks-runnable-pilot.zip',J.zip(files),'application/zip');toast('Pilot package exported; nothing executed');}catch(error){executionError=error.message;}finally{executionBusy=false;render();}}
const pilotPhases=[['prepare','1. Prepare draft'],['run','2. Validate & run'],['observe','3. Observe & timeline'],['recover','4. Inspect & recover']];
function pilot(){const draft=pilotDraft(),options=B.candidates(raw);if(!options.length)return draft;if(!pilotPhases.some(([id])=>id===pilotPhase))pilotPhase='prepare';const state=X.lifecycle(executionPlan(),executionEvidence,executionObservation,executionInspection,executionCleanup);return `<section class="panel pilot-summary"><div class="panelhead"><div><h2>Selected pilot</h2><p>${esc(state.status)} · production gate closed</p></div><button class="secondary" data-action="executionimport">Import run / observation / recovery receipt</button></div><label>Deployment<select id="pilotSelect" aria-label="Pilot Deployment">${options.map(o=>`<option value="${esc(o.id)}" ${o.id===pilotChoice?'selected':''}>${esc(o.namespace+'/'+o.name)}</option>`).join('')}</select></label><p>${esc(state.detail)}</p>${state.recoveryRequired?'<div class="notice">Review this existing run before further operations. <button class="secondary" data-pilot-phase="recover">Open recovery</button></div>':''}<div class="error" role="alert">${esc(executionError)}</div><nav class="pilot-steps" aria-label="Pilot workflow">${pilotPhases.map(([id,title])=>`<button data-pilot-phase="${id}" class="${pilotPhase===id?'active':''}" ${pilotPhase===id?'aria-current="step"':''}>${title}</button>`).join('')}</nav></section><p class="pilot-save-note">Save or update the current form before moving to another step; unsaved field edits are not retained.</p><div class="pilot-stage" data-current-phase="${pilotPhase}">${pilotPhase==='prepare'?draft:pilotPhase==='run'?executionWorkbench():pilotPhase==='observe'?observationWorkbench()+timelineWorkbench():recoveryWorkbench()}</div><div class="toolbar pilot-footer"><a href="#overview" class="textlink">← Action checklist</a><a href="#target" class="textlink">Target preflight →</a><a href="#acceptance" class="textlink">Application acceptance →</a><a href="#project" class="textlink">Save / hand off →</a></div>`;}
function pilotDraft(){
 const options=B.candidates(raw);if(!options.length)return '<section class="panel"><h2>No Deployments in this inventory</h2><p>This generator supports apps/v1 Deployments and isolated ClusterIP Services. Import an inventory containing a stateless Deployment.</p></section>';
 if(!options.some(x=>x.id===pilotChoice)){pilotChoice=options.find(x=>x.name==='web-pilot')?.id||options[0].id;pilotImages={};pilotSA='';}
 const r=report.resources.find(x=>E.id(x)===pilotChoice),p=E.pod(r),images=[...new Set([...p?.containers||[],...p?.initContainers||[]].map(c=>c.image).filter(Boolean))],b=pilotBundle();
 return `<div class="banner"><div><strong>Prepare a pilot for review</strong><p>Creates Kubernetes JSON manifests for one Deployment and its isolated ClusterIP Services. Namespace is preserved. Ingress, policies, credentials and platform controllers remain separate prerequisites.</p></div>${badge('Draft only')}</div><section class="panel"><form id="pilotForm"><h3>2. Explicit destination mappings</h3><div class="formgrid">${images.map((image,i)=>`<label>Image ${i+1}<span class="mono">${esc(image)}</span><input name="image-${i}" value="${esc(pilotImages[image]||imagePilotRefs[image]||image)}" data-source-image="${esc(image)}" aria-label="Destination image for ${esc(image)}" required></label>`).join('')}<label>Destination service account<input name="serviceAccount" value="${esc(pilotSA||p?.serviceAccountName||p?.serviceAccount||'default')}" required></label></div><p>Images are referenced, never copied. No namespace remapping is performed. Cloud identities require an explicit reviewed account mapping and target evidence.</p><button type="submit">Update draft preview</button></form></section><section class="panel"><div class="panelhead"><h2>3. Review generated draft</h2>${badge(b.blockers.length?'Blocker':'Unverified')}</div><p>${esc(b.status)} · ${b.manifests.items.length} resources · ${b.changes.length} changes · ${b.prerequisites.length} prerequisites</p>${b.blockers.length?`<div class="notice"><b>Resolve ${b.blockers.length} blocker(s) before validation.</b>${b.blockers.map(x=>`<p>${esc(x.resource)}: ${esc(x.reason)}</p>`).join('')}</div>`:''}<details open><summary>Transformation preview</summary><div class="tablewrap"><table><thead><tr><th>Resource / field</th><th>Source</th><th>Draft</th></tr></thead><tbody>${b.changes.map(c=>`<tr><td>${esc(c.resource)}<small>${esc(c.path)}</small></td><td class="mono">${esc(c.before)}</td><td class="mono">${esc(c.after)}</td></tr>`).join('')||'<tr><td colspan="3">No explicit transformations. Review all prerequisites.</td></tr>'}</tbody></table></div></details><details><summary>Generated Kubernetes List (JSON)</summary><pre>${esc(JSON.stringify(b.manifests,null,2))}</pre></details><h3>Required prerequisites · unverified</h3>${b.prerequisites.map(x=>`<div class="workitem"><b class="mono">${esc(x.resource)}</b><p>${esc(x.action)}</p></div>`).join('')}${b.omitted.length?`<h3>Not included in draft</h3><p class="mono">${b.omitted.map(esc).join('<br>')}</p>`:''}</section><section class="panel"><h2>4. Download review files</h2><p>Keep these files together. Review against your complete desired-state repository; inventory exports omit configuration values. The script requires an explicit context and runs only server dry-run and diff. It stops when the draft has blockers.</p><div class="toolbar"><button data-action="pilotmanifest">↓ pilot-draft.json</button><button class="secondary" data-action="pilotreview">↓ pilot-review.json</button><button class="secondary" data-action="pilotvalidate">↓ validate-pilot.sh</button></div><pre>bash validate-pilot.sh TARGET_CONTEXT</pre><div class="notice">This validation script performs no deployment or cutover. A successful dry-run does not prove image pulls, connectivity, authorization, performance or application correctness. Resolve prerequisites and perform those tests separately.</div></section>`;
}
function targetValidation(){const p=targetCheckPlan(),summary=C.summary(p,targetCheckEvidence);return `<div class="banner"><div><strong>Run scoped checks from your kubectl workstation</strong><p>Selected pilot: ${esc(pilotChoice||'None')}. The runner performs named reads and server-side dry-run only. Import a target inventory containing kube-system UID before the final dry-run; unknown identity/prerequisites keep that check skipped.</p></div>${badge('Production gate closed')}</div><section class="panel"><h2>1. Configure target preflight scope</h2><form id="targetChecksForm"><label>Expected kubectl context (optional name binding)<input name="context" value="${esc(targetCheckSettings.context)}" maxlength="300"></label><label class="check"><input name="includeRouting" type="checkbox" ${targetCheckSettings.includeRouting?'checked':''}>Include the selected routing draft</label><button type="submit">Update preflight scope</button></form><p>Expected target UID: <span class="mono">${esc(p.expectedClusterUID||'Not supplied')}</span>. Source UID: <span class="mono">${esc(p.sourceClusterUID||'Not supplied')}</span>.</p><div class="toolbar"><a href="#pilot" class="textlink">Select/configure pilot →</a><a href="#compare" class="textlink">Import target inventory →</a></div>${p.blockers.length?`<div class="notice">${p.blockers.length} known blocker(s) will prevent dry-run.${p.blockers.map(b=>`<p>${esc(b.reason)}</p>`).join('')}</div>`:''}</section><section class="panel"><div class="panelhead"><h2>2. Export and run locally</h2><button data-action="targetcheckplan">↓ target-plan.json</button></div><a href="target-preflight.py" download class="textlink">↓ target-preflight.py</a><pre>python3 target-preflight.py --context TARGET_CONTEXT --plan target-plan.json --output target-results.json</pre><p>Requires Python 3 and configured kubectl. It uses the explicit context on every command and never switches current context. Namespace preparation and referenced objects must exist. Server-side dry-run requires normal create/patch authorization and compatible admission webhooks. Failed reads are errors, not evidence of missing resources.</p><p>Secret/ConfigMap checks request named objects locally with name-only CLI output; values, raw objects and raw diagnostics are not included in the report. No test Pod, registry pull, policy change or persistent deployment occurs.</p><div class="notice">${p.limitations.map(esc).join('<br>')}</div></section><section class="panel"><div class="panelhead"><h2>3. Import scoped observations</h2><button data-action="targetcheckimport">Import target-results.json</button></div><div class="error" role="alert">${esc(targetCheckError)}</div><p>${summary.reportedPass} of ${summary.total} checks reported pass · ${summary.unresolved} unresolved. These are check outcomes, not a migration readiness score.</p><div class="tablewrap"><table><thead><tr><th>Check</th><th>Reported outcome</th><th>Observation</th></tr></thead><tbody>${summary.rows.map(r=>`<tr><td>${esc(r.title)}<small>${esc(r.id)}</small></td><td>${esc(r.result?.status||'Not run')}</td><td>${esc(r.result?.detail||'No imported observation')}<small>${esc(r.result?.observedAt||'')}</small></td></tr>`).join('')}</tbody></table></div>${targetCheckEvidence?`<p>Reported context: ${esc(targetCheckEvidence.context)}. ${esc(targetCheckEvidence.note)}</p>`:''}<div class="notice">${esc(summary.reason)} Scope/settings changes invalidate previous observations. Project files and full migration ZIPs include the plan and external results.</div><button class="secondary" data-action="targetcheckreview">↓ target-preflight-review.json</button></section>`;}
function target(){return targetValidation()+`<section class="panel"><h2>Destination assumptions</h2><p>These settings customize the assessment and report. Verify them against your actual VKS environment.</p><form id="targetForm"><div class="formgrid"><label>VKS release<input name="release" value="${esc(profile.release)}" placeholder="e.g. your deployed release" required></label><label>Target Kubernetes version<input name="kubernetes" value="${esc(profile.kubernetes)}" pattern="v?1\.[0-9]+(\.[0-9]+)?" title="Use 1.minor or 1.minor.patch" required></label><label>Primary CNI<select name="cni">${['Antrea','Other / unverified'].map(x=>`<option ${profile.cni===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Gateway / ingress controller<input name="gateway" value="${esc(profile.gateway)}" required></label><label>Target storage class<input name="storage" value="${esc(profile.storage)}" required></label><label>Image strategy<select name="imagePolicy">${['Reuse registry','Mirror to Harbor','Migrate to Harbor'].map(x=>`<option ${profile.imagePolicy===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label></div><div class="notice">Default values are planning assumptions. They do not imply these versions or integrations are supported together. ${targetRaw?'Destination inventory is available in Target comparison; this form still contains declared assumptions.':'No target inventory has been imported.'}</div><button type="submit">Update assessment</button></form></section><section class="panel"><h2>Execution roadmap</h2><p>Next engineering stages: a secure collector service, a versioned VKS capability catalog, source-repository analysis, target preflight, registry copying, broader transformations, and controlled execution with recorded approvals and recovery.</p><p>This release provides API inventory analysis and planning. It generates scoped stateless draft manifests. It does not connect to clusters, move data or perform a cutover.</p></section>`;}
function changesWorkbench(){const r=stagedSnapshot?.review,labels={Added:'Newly observed',Removed:'No longer observed',Changed:'Fields changed',Recreated:'Different object UID'};return `<div class="banner"><div><strong>Review snapshots before replacement</strong><p>Staging leaves inventories, settings and evidence intact. Adoption replaces the selected snapshot and clears affected evidence. No cluster is contacted.</p></div>${badge('Read-only comparison')}</div><section class="panel"><h2>1. Stage an inventory</h2><div class="toolbar"><label>Snapshot to refresh<select id="changeSide"><option value="source" ${changeSide==='source'?'selected':''}>Source inventory</option><option value="target" ${changeSide==='target'?'selected':''}>Target inventory</option></select></label><button data-action="changestage">Choose fresh inventory JSON</button><button class="secondary" data-action="changeclear">Discard review</button></div><p>Use the same collection scope for a useful comparison. Up to 15 MB / 30,000 resources. Staging and the latest review are session-only; export the review separately. Saved project files contain the adopted inventories.</p><div class="error" role="alert">${esc(changeError)}</div>${lastChangeReview?`<p>Latest adoption: ${esc(lastChangeReview.side)} · ${esc(lastChangeReview.adoptedAt)}. <button class="secondary" data-action="changelast">↓ Adopted change review</button></p>`:''}</section>${r?`<section class="panel"><div class="panelhead"><div><h2>2. Review ${esc(r.side)} changes</h2><p>${esc(stagedSnapshot.filename)} · ${r.before.resources} → ${r.incoming.resources} observed resources</p></div><button class="secondary" data-action="changeexport">↓ Pending change review</button></div><div class="stats">${Object.entries(labels).map(([key,label])=>`<div class="stat"><small>${label}</small><strong>${r.counts[key.toLowerCase()]}</strong></div>`).join('')}</div><p>${r.counts.unchanged} resources have no compared field changes. Kubernetes version: ${esc(r.before.kubernetes)} → ${esc(r.incoming.kubernetes)}. Collection metadata: ${r.collectionChanged?'changed':'no compared changes'}.</p><p>Cluster identity: <b>${esc(r.clusterIdentity)}</b> · kube-system UID ${esc(r.before.clusterUID||'not observed')} → ${esc(r.incoming.clusterUID||'not observed')}.</p><p>Reported collection errors: ${esc(r.collection.before.errors??'not supplied')} → ${esc(r.collection.incoming.errors??'not supplied')}. Missing resources may reflect collection gaps rather than deletions.</p><div class="toolbar"><label>Changes to show<select id="changeFilter">${['All',...Object.keys(labels)].map(x=>`<option ${changeFilter===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="tablewrap"><table><thead><tr><th>Observed difference</th><th>Resource identity</th><th>Changed field paths (values omitted)</th></tr></thead><tbody>${r.rows.filter(x=>changeFilter==='All'||x.change===changeFilter).slice(changePage*100,(changePage+1)*100).map(x=>`<tr><td>${esc(labels[x.change])}</td><td class="mono">${esc(x.resource)}<small>${esc(x.apiGroup)}</small></td><td class="mono">${x.paths.slice(0,20).map(esc).join('<br>')||'Whole resource presence differs'}${x.paths.length>20||x.truncated?'<small>More paths in JSON review; maximum 100 per resource.</small>':''}</td></tr>`).join('')||'<tr><td colspan="3">No differences in this filter. This does not establish drift-free operation.</td></tr>'}</tbody></table></div><div class="toolbar"><button class="secondary" data-action="changeprev" ${changePage===0?'disabled':''}>Previous</button><span>Page ${changePage+1} of ${Math.max(1,Math.ceil(r.rows.filter(x=>changeFilter==='All'||x.change===changeFilter).length/100))}</span><button class="secondary" data-action="changenext" ${(changePage+1)*100>=r.rows.filter(x=>changeFilter==='All'||x.change===changeFilter).length?'disabled':''}>Next</button></div></section><section class="panel"><h2>3. Adopt reviewed snapshot</h2><p>${r.side==='source'?'Source adoption resets source-bound mappings, wave assignments, pilot/routing selections, stateful plans, acceptance definitions and registry results. Target inventory, destination profile and GitOps settings are retained for review.':'Target adoption clears class mappings, security mappings, security/preflight/acceptance results, target storage evidence and measured recovery values. Source pilot, registry records and planning definitions remain for review; registry records do not verify target pulls. A changed reported cluster UID also clears target context labels.'}</p><p>Save your current project before adopting if you need its existing plans and evidence. Adoption is a local workspace replacement; it never applies or deletes Kubernetes resources.</p><form id="adoptSnapshotForm">${r.clusterIdentity==='Different reported UID'?'<label class="notice"><input type="checkbox" name="identityReviewed" required> I reviewed the different reported cluster UID and intend to replace this snapshot.</label>':''}<button type="submit">Adopt reviewed ${esc(r.side)} snapshot</button></form></section><section class="panel"><h2>Comparison limits</h2>${r.limitations.map(x=>`<p>${esc(x)}</p>`).join('')}</section>`:'<section class="panel"><h2>Current inventory stays active</h2><p>Choose a fresh source or target snapshot to see its changes. No pending inventory is included in project exports.</p></section>'}`;}
function adoptStagedSnapshot(identityReviewed=false){if(!stagedSnapshot)throw Error('Stage and review an inventory first.');const p=stagedSnapshot;if(p.sourceRef!==raw||p.targetRef!==targetRaw)throw Error('Workspace inventories changed; stage this snapshot again.');if(p.review.clusterIdentity==='Different reported UID'&&!identityReviewed)throw Error('Review the changed cluster identity before adoption.');const s=JSON.parse(JSON.stringify(projectState()));s[p.side==='source'?'source':'target']=p.inventory;s.mappings={};s.checks=[];s.security={revision:globalThis.crypto?.randomUUID?.()||String(Date.now())+'-'+Math.random(),decisions:{},choice:'',evidence:null};s.preflight.evidence=null;s.acceptance.evidence=null;s.execution.evidence=null;s.execution.observation=null;s.execution.inspection=null;s.execution.cleanup=null;if(p.side==='source'){s.sourceMode='Imported';s.execution={settings:X.settings(),evidence:null};s.wavePlanning=Q.settings(p.inventory);s.storage={decisions:{},choice:''};s.acceptance={settings:A.settings(),evidence:null};s.images={...s.images,overrides:{},pilotRefs:{},evidence:null};s.pilot={choice:'',images:{},serviceAccount:''};s.routing={choice:'',mode:'Ingress',ingressClass:'',gateway:'',gatewayNamespace:'',listener:''};}else {s.targetName=p.filename;for(const d of Object.values(s.storage.decisions))for(const k of ['restoreEvidence','integrityEvidence','rollbackEvidence','portabilityEvidence','measuredRpoMinutes','measuredRestoreMinutes'])delete d[k];if(p.review.clusterIdentity==='Different reported UID'){s.preflight.settings.context='';s.acceptance.settings.targetContext='';}}const prepared=J.restore({kind:'VKSProject',schemaVersion:1,name:projectName,notes:projectNotes,savedAt:'',state:s}),review={...p.review,status:'Adopted',adoptedAt:new Date().toISOString()};applyProject(prepared);lastChangeReview=review;location.hash='changes';render();toast('Reviewed snapshot adopted; affected evidence cleared');}
function render(){if(!report)return;view=Object.hasOwn(views,location.hash.slice(1))?location.hash.slice(1):'overview';const group=W.groupFor(view);$('#title').textContent=views[view][2];$('#subtitle').textContent=views[view][3];$('#mode').textContent=mode==='Demo'?'DEMO INVENTORY':'IMPORTED INVENTORY';$('#nav').innerHTML=W.groups.map(g=>`<a href="#${g.id}" class="${group.id===g.id?'active':''}" ${group.id===g.id?'aria-current="true"':''}><span class="navicon">${g.icon}</span>${g.label}</a>`).join('');$('#workbenchTabs').innerHTML=group.views.length>1?group.views.map(k=>`<a href="#${k}" class="${view===k?'active':''}" ${view===k?'aria-current="page"':''}>${esc(views[k][1])}</a>`).join(''):'';$('#content').innerHTML=({changes:changesWorkbench,acceptance:acceptanceWorkbench,project:projectView,overview,inventory,dependencies,findings:()=>assessment(),security:securityWorkbench,plan,compare,images,routing,storage,gitops,pilot,target}[view])();$('#workspaceContext').innerHTML=workspaceContext();updateResults();if(view==='dependencies')graph();}
function updateResults(){if(view==='inventory')$('#results').innerHTML=tableInventory();if(view==='findings')$('#results').innerHTML=findingRows(filteredFindings());}
function detailFinding(id){const f=report.findings.find(x=>x.id===id);if(!f)return;$('#detailTitle').textContent=f.title;$('#detailBody').innerHTML=`${badge(f.severity)} <span class="muted">${esc(f.id)} · ${esc(f.category)}</span><div class="detailsection"><h3>Resource</h3><p class="mono">${esc(f.resource)}</p></div><div class="detailsection"><h3>Observed evidence</h3><p>${esc(f.evidence)}</p></div><div class="detailsection"><h3>Required action</h3><p>${esc(f.action)}</p></div><div class="detailsection"><h3>Validation</h3><p>${esc(f.validation)}</p></div><div class="notice">Finding status: open. No automatic equivalence or production readiness has been established.</div>`;$('#detail').showModal();}
function resourceDetail(id){const r=report.resources.find(r=>E.id(r)===id);if(!r)return;$('#detailTitle').textContent=r.metadata.name;$('#detailBody').innerHTML=`<p>${esc(r.kind)} · ${esc(r.metadata.namespace||'Cluster scope')}</p><h3>Sanitized resource</h3><pre>${esc(JSON.stringify(r,null,2))}</pre><p>Data payloads, inline env values, status and managed fields are omitted. Other resource fields may remain sensitive.</p>`;$('#detail').showModal();}
function planText(){return H.markdown(handoffReview())+'\n\n'+'# Local pilot execution\n\n'+JSON.stringify({plan:executionPlan(),evidence:executionEvidence,observation:executionObservation,observationHistory:executionHistory,inspection:executionInspection,cleanup:executionCleanup},null,2)+'\n\n'+Q.markdown(wavePlan())+'\n\n'+A.markdown(acceptancePlan(),acceptanceEvidence)+'\n\n'+'# Migration journey\n\n'+JSON.stringify(journeySummary(),null,2)+'\n\n'+'# Target preflight\n\n'+JSON.stringify(C.summary(targetCheckPlan(),targetCheckEvidence),null,2)+'\n\n'+'# GitOps handoff\n\n'+JSON.stringify(gitopsBundle().review,null,2)+'\n\n'+'# Stateful migration workstream\n\n'+T.markdown(storagePlan())+'\n\n'+'# Security workstream\n\n'+JSON.stringify({plan:securityPlan(),summary:securitySummary()},null,2)+'\n\n'+'# Inventory-informed sequence\n\n'+JSON.stringify(migrationPlan(),null,2)+'\n\n# Target comparison\n\n'+JSON.stringify(comparison(),null,2)+'\n\n'+'# VKS Migration Plan\n\nGenerated: '+report.generatedAt+'\nMode: '+mode+'\nProduction readiness: UNVERIFIED\n\n'+waves.map(([t,d,tasks],i)=>`## ${i+1}. ${t}\n${d}\n\n`+tasks.map((t,j)=>`- [${checks.has(i+'-'+j)?'x':' '}] ${t} (planning note only)`).join('\n')).join('\n\n')+'\n\n## Findings\n'+report.findings.map(f=>`\n### ${f.id}: ${f.title} [${f.severity}]\nResource: ${f.resource}\nEvidence: ${f.evidence}\nAction: ${f.action}\nValidation: ${f.validation}\n`).join('');}
$('#importTop').onclick=()=>$('#importDialog').showModal();$('#closeImport').onclick=()=>$('#importDialog').close();$('#closeDetail').onclick=()=>$('#detail').close();$('#chooseFile').onclick=()=>$('#file').click();$('#export').onclick=()=>{download('vks-migration-assessment.json',JSON.stringify({...report,inventoryMode:mode,pilotHandoff:handoffReview(),pilotExecution:{plan:executionPlan(),evidence:executionEvidence,observation:executionObservation,observationHistory:executionHistory,inspection:executionInspection,cleanup:executionCleanup},migrationWaves:wavePlan(),inventoryChangeReview:lastChangeReview,applicationAcceptance:{plan:acceptancePlan(),evidence:acceptanceEvidence,summary:acceptanceSummary()},migrationJourney:journeySummary(),targetComparison:comparison(),migrationPlan:migrationPlan(),targetPreflight:{plan:targetCheckPlan(),evidence:targetCheckEvidence,summary:C.summary(targetCheckPlan(),targetCheckEvidence)},gitopsHandoff:gitopsBundle().review,statefulMigrationPlan:storagePlan(),securityWorkstream:{plan:securityPlan(),summary:securitySummary(),evidence:securityEvidence},routingDraft:routeChoice?routingBundle():null,imageMigrationPlan:imagePlan(),imageRegistryEvidence:imageEvidence,planningNotes:[...checks]},null,2));toast('Assessment report exported');};
async function stageSnapshotFile(f,side){const sourceRef=raw,targetRef=targetRaw,expectedSide=changeSide,token=++changeStageToken;if(f.size>15*1024*1024)throw Error('File exceeds 15 MB.');const inventory=D.prepare(JSON.parse(await f.text())),review=D.compare(side==='source'?sourceRef:targetRef,inventory,side);if(token!==changeStageToken||sourceRef!==raw||targetRef!==targetRaw||expectedSide!==changeSide)throw Error('Workspace changed during import. Choose the snapshot again.');E.analyze(inventory,effectiveProfile());stagedSnapshot={side,filename:f.name||'inventory.json',inventory,review,sourceRef,targetRef};changeSide=side;changeError='';changePage=0;changeFilter='All';location.hash='changes';}
$('#executionFile').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;try{if(f.size>15*1024*1024)throw Error('File exceeds 15 MB.');const input=JSON.parse(await f.text());if(input.kind==='PilotObservationResult'){const history=X.appendObservation(executionPlan(),executionEvidence,executionHistory,input);executionHistory=history;executionObservation=history.records.at(-1)||null;}else if(input.kind==='PilotInspectionResult'){executionInspection=X.recoveryEvidence(executionPlan(),executionEvidence,input);executionCleanup=null;}else if(input.kind==='PilotCleanupResult'){executionCleanup=X.recoveryEvidence(executionPlan(),executionEvidence,input,executionInspection);}else {const receipt=X.evidence(executionPlan(),input);if(JSON.stringify(receipt)!==JSON.stringify(executionEvidence)){executionObservation=null;executionHistory={records:[],truncated:false};executionInspection=null;executionCleanup=null;}executionEvidence=receipt;}pilotPhase=input.kind==='PilotObservationResult'?'observe':['PilotInspectionResult','PilotCleanupResult'].includes(input.kind)?'recover':'run';executionError='';toast('Historical local pilot observations imported; production gate closed');}catch(error){executionError=error.message;}finally{ev.target.value='';render();}};
$('#changeFile').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;try{await stageSnapshotFile(f,changeSide);}catch(error){changeError=error.message;}finally{ev.target.value='';render();}};
$('#file').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;try{if(mode!=='Demo'){await stageSnapshotFile(f,'source');$('#importError').textContent='';$('#importDialog').close();render();toast('Source replacement staged for review');return;}if(f.size>15*1024*1024)throw Error('File exceeds 15 MB. Use a smaller inventory.');const parsed=JSON.parse(await f.text()),next=E.analyze(parsed,effectiveProfile());if(!next.resources.length)throw Error('Inventory contains no resources.');clearChangeReview();raw=E.normalize(parsed);report=next;mode='Imported';executionSettings=X.settings();waveSettings=Q.settings(raw);waveWorkload='';waveError='';storageSettings={};storageChoice='';acceptanceSettings=A.settings();resetSecurity();resetRouting();clearImageEvidence();imageOverrides={};resetPilot();mappings={};checks.clear();$('#importError').textContent='';$('#importDialog').close();location.hash='overview';render();toast(`${report.resources.length} resources analyzed locally`);}catch(e){$('#importError').textContent=e.message;}finally{ev.target.value='';}};
$('#acceptanceFile').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;try{if(f.size>15*1024*1024)throw Error('File exceeds 15 MB.');acceptanceEvidence=A.evidence(acceptancePlan(),JSON.parse(await f.text()));acceptanceError='';toast('Acceptance records imported as external observations');}catch(error){acceptanceError=error.message;}finally{ev.target.value='';render();}};
$('#targetCheckFile').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;try{if(f.size>15*1024*1024)throw Error('File exceeds 15 MB.');targetCheckEvidence=C.evidence(targetCheckPlan(),JSON.parse(await f.text()));targetCheckError='';toast('External target observations imported; production gate remains closed');}catch(error){targetCheckError=error.message;}finally{ev.target.value='';render();}};
$('#projectFile').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;projectLoading=true;try{if(f.size>J.MAX_BYTES)throw Error('Project exceeds the 75 MB limit.');const prepared=J.restore(JSON.parse(await f.text()));applyProject(prepared);location.hash='project';toast('Project restored locally; evidence remains externally reported');}catch(error){projectError=error.message;location.hash='project';}finally{projectLoading=false;ev.target.value='';render();}};
$('#securityEvidenceFile').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;try{if(f.size>15*1024*1024)throw Error('File exceeds 15 MB.');securityEvidence=S.importEvidence(securityPlan(),JSON.parse(await f.text()));securityError='';toast('External security records imported; production gate remains closed');}catch(error){securityError=error.message;}finally{ev.target.value='';render();}};
$('#imageResultsFile').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;try{if(f.size>15*1024*1024)throw Error('File exceeds 15 MB.');if(imagePlan().errors.length)throw Error('Resolve image plan errors first.');imageEvidence=I.evidence(imagePlan(),JSON.parse(await f.text()));imageError='';imagePilotRefs={};invalidateSecurity();toast('External registry results imported; target pull access remains unverified');}catch(error){imageError=error.message;}finally{ev.target.value='';render();}};
$('#targetFile').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;try{if(targetRaw){await stageSnapshotFile(f,'target');targetError='';toast('Target replacement staged for review');return;}if(f.size>15*1024*1024)throw Error('File exceeds 15 MB.');const next=E.normalize(JSON.parse(await f.text()));if(!next.items.length)throw Error('Target inventory contains no resources.');clearChangeReview();targetRaw=next;clearStorageTargetEvidence();resetSecurity();report=E.analyze(raw,effectiveProfile());targetName=f.name;mappings={};checks.clear();targetError='';toast('Target evidence imported; behavior remains unverified');}catch(error){targetError=error.message;}finally{ev.target.value='';render();}};
document.addEventListener('click',e=>{const phase=e.target.closest('[data-pilot-phase]');if(phase){if(pilotPhases.some(([id])=>id===phase.dataset.pilotPhase))pilotPhase=phase.dataset.pilotPhase;render();return;}const scope=e.target.closest('[data-checklist-scope]');if(scope){if(['All','Selected pilot','Inventory','Project'].includes(scope.dataset.checklistScope))checklistScope=scope.dataset.checklistScope;render();return;}const jump=e.target.closest('[data-checklist-view]');if(jump){if(Object.hasOwn(views,jump.dataset.checklistView)){if(pilotPhases.some(([id])=>id===jump.dataset.checklistPhase))pilotPhase=jump.dataset.checklistPhase;location.hash='#'+jump.dataset.checklistView;render();}return;}const ac=e.target.closest('[data-acceptance-case]');if(ac){acceptanceChoice=ac.dataset.acceptanceCase;render();return;}const claim=e.target.closest('[data-storage-claim]');if(claim){storageChoice=claim.dataset.storageClaim;render();return;}const control=e.target.closest('[data-security-control]');if(control){securityChoice=control.dataset.securityControl;render();return;}const f=e.target.closest('[data-finding]');if(f)return detailFinding(f.dataset.finding);const r=e.target.closest('[data-resource]');if(r)return resourceDetail(r.dataset.resource);const a=e.target.closest('[data-action]');if(a?.dataset.action==='checklistjson')download('migration-action-checklist.json',JSON.stringify(H.checklist(handoffReview()),null,2));if(a?.dataset.action==='handoffjson')download('pilot-handoff.json',JSON.stringify(handoffReview(),null,2));if(a?.dataset.action==='handoffmd')download('pilot-handoff.md',H.markdown(handoffReview()),'text/markdown');if(a?.dataset.action==='executiontimeline')download('pilot-timeline.json',JSON.stringify(pilotTimeline(),null,2));if(a?.dataset.action==='executionzip')exportExecutionPackage();if(a?.dataset.action==='executionimport')$('#executionFile').click();if(a?.dataset.action==='wavejson')download('migration-wave-plan.json',JSON.stringify(wavePlan(),null,2));if(a?.dataset.action==='wavemd')download('migration-wave-runbook.md',Q.markdown(wavePlan()),'text/markdown');if(a?.dataset.action==='waveadd'){try{if(waveSettings.waves.length>=12)throw Error('Maximum 12 waves.');const id='wave-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8));waveSettings=Q.settings(raw,{...waveSettings,waves:[...waveSettings.waves,{id,name:'New wave',owner:'',entryCriteria:'',exitCriteria:'',rollback:''}]});waveChoice=id;waveError='';}catch(error){waveError=error.message;}render();}if(a?.dataset.action==='wavemove'){try{waveSettings=Q.settings(raw,Q.move(waveSettings,a.dataset.waveId,Number(a.dataset.direction)));waveError='';}catch(error){waveError=error.message;}render();}if(a?.dataset.action==='waveremove'){try{waveSettings=Q.settings(raw,Q.remove(waveSettings,waveChoice));waveChoice=waveSettings.waves[0].id;waveError='';}catch(error){waveError=error.message;}render();}if(a?.dataset.action==='waveprev'){waveTablePage=Math.max(0,waveTablePage-1);render();}if(a?.dataset.action==='wavenext'){if((waveTablePage+1)*100<Q.catalog(raw).length)waveTablePage++;render();}if(a?.dataset.action==='changestage')$('#changeFile').click();if(a?.dataset.action==='changeclear'){clearChangeReview();render();}if(a?.dataset.action==='changeexport'&&stagedSnapshot)download('inventory-change-review.json',JSON.stringify(stagedSnapshot.review,null,2));if(a?.dataset.action==='changelast'&&lastChangeReview)download('adopted-inventory-change-review.json',JSON.stringify(lastChangeReview,null,2));if(a?.dataset.action==='changeprev'){changePage=Math.max(0,changePage-1);render();}if(a?.dataset.action==='changenext'&&stagedSnapshot){const count=stagedSnapshot.review.rows.filter(x=>changeFilter==='All'||x.change===changeFilter).length;if((changePage+1)*100<count)changePage++;render();}if(a?.dataset.action==='acceptanceplan')download('acceptance-plan.json',JSON.stringify(acceptancePlan(),null,2));if(a?.dataset.action==='acceptancetemplate')download('acceptance-evidence-template.json',JSON.stringify(A.template(acceptancePlan()),null,2));if(a?.dataset.action==='acceptanceimport')$('#acceptanceFile').click();if(a?.dataset.action==='acceptancereview')download('acceptance-review.json',JSON.stringify({plan:acceptancePlan(),evidence:acceptanceEvidence,summary:acceptanceSummary()},null,2));if(a?.dataset.action==='acceptancemd')download('acceptance-workbook.md',A.markdown(acceptancePlan(),acceptanceEvidence),'text/markdown');if(a?.dataset.action==='targetcheckplan')download('target-plan.json',JSON.stringify(targetCheckPlan(),null,2));if(a?.dataset.action==='targetcheckimport')$('#targetCheckFile').click();if(a?.dataset.action==='targetcheckreview')download('target-preflight-review.json',JSON.stringify({plan:targetCheckPlan(),summary:C.summary(targetCheckPlan(),targetCheckEvidence),evidence:targetCheckEvidence},null,2));if(a?.dataset.action==='gitopszip')download('vks-gitops-handoff.zip',J.zip(gitopsBundle().files),'application/zip');if(a?.dataset.action==='gitopsreview')download('gitops-review.json',JSON.stringify(gitopsBundle().review,null,2));if(a?.dataset.action==='storageexport')download('stateful-plan.json',JSON.stringify(storagePlan(),null,2));if(a?.dataset.action==='storagemd')download('stateful-runbook.md',T.markdown(storagePlan()),'text/markdown');if(a?.dataset.action==='projectopen')$('#projectFile').click();if(a?.dataset.action==='projectsave'){try{const snapshot=projectSnapshot();download('migration.vks-project.json',JSON.stringify(snapshot,null,2));projectSavedAt=snapshot.savedAt;projectError='';toast('Project JSON saved');render();}catch(error){projectError=error.message;render();}}if(a?.dataset.action==='projectbundle')exportProjectBundle();if(a?.dataset.action==='securityplan')download('security-plan.json',JSON.stringify(securityPlan(),null,2));if(a?.dataset.action==='securitytemplate')download('security-evidence-template.json',JSON.stringify(S.template(securityPlan()),null,2));if(a?.dataset.action==='securityexport')download('security-review.json',JSON.stringify({plan:securityPlan(),summary:securitySummary(),evidence:securityEvidence},null,2));if(a?.dataset.action==='securityimport')$('#securityEvidenceFile').click();if(a?.dataset.action==='routemanifest')download('routing-draft.json',JSON.stringify(routingBundle().manifests,null,2));if(a?.dataset.action==='routereview')download('routing-review.json',JSON.stringify(routingBundle(),null,2));if(a?.dataset.action==='routevalidate')download('validate-routing.sh',B.validationScript(routingBundle()).replaceAll('pilot-draft.json','routing-draft.json').replaceAll('pilot-review.json','routing-review.json').replaceAll('validate-pilot.sh','validate-routing.sh'),'text/x-shellscript');if(a?.dataset.action==='imageplan'&&!imagePlan().errors.length)download('image-plan.json',JSON.stringify(imagePlan(),null,2));if(a?.dataset.action==='imagecommands'&&!imagePlan().errors.length)download('image-copy-preview.sh',imageCommands(),'text/x-shellscript');if(a?.dataset.action==='imageresults'&&!imagePlan().errors.length)$('#imageResultsFile').click();if(a?.dataset.action==='imageuseplanned'&&!imagePlan().errors.length){imagePilotRefs=Object.fromEntries(imagePlan().rows.map(r=>[r.source,r.destination]));pilotImages={};invalidateSecurity();toast('Planned references supplied; review image prerequisites in the pilot');render();}if(a?.dataset.action==='imageusepins'&&imageEvidence){imagePilotRefs=Object.fromEntries(imageEvidence.results.filter(r=>r.pinnedDestination).map(r=>[r.source,r.pinnedDestination]));pilotImages={};invalidateSecurity();toast('Reported registry digest pins supplied; target pulls remain unverified');render();}if(a?.dataset.action==='pilotmanifest')download('pilot-draft.json',JSON.stringify(pilotBundle().manifests,null,2));if(a?.dataset.action==='pilotreview')download('pilot-review.json',JSON.stringify(pilotBundle(),null,2));if(a?.dataset.action==='pilotvalidate')download('validate-pilot.sh',B.validationScript(pilotBundle()),'text/x-shellscript');if(a?.dataset.action==='targetimport')$('#targetFile').click();if(a?.dataset.action==='targetclear'){clearChangeReview();targetRaw=null;clearStorageTargetEvidence();resetSecurity();report=E.analyze(raw,effectiveProfile());mappings={};targetName='';targetError='';checks.clear();render();}if(a?.dataset.action==='comparisonexport')download('vks-target-comparison.json',JSON.stringify(comparison(),null,2));if(a?.dataset.action==='import')$('#importDialog').showModal();if(a?.dataset.action==='planexport')download('vks-migration-plan.md',planText(),'text/markdown');const t=e.target.closest('[data-tab]');if(t){inventoryTab=t.dataset.tab;filter='';render();}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&(e.target.dataset.finding||e.target.dataset.resource)){e.preventDefault();e.target.click();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){filter=e.target.value;updateResults();}});
document.addEventListener('change',e=>{if(e.target.id==='waveChoice'){waveChoice=e.target.value;render();}if(e.target.id==='waveWorkload'){waveWorkload=e.target.value;render();}if(e.target.id==='changeSide'){changeStageToken++;changeSide=e.target.value;stagedSnapshot=null;changeError='';changePage=0;render();}if(e.target.id==='changeFilter'){changeFilter=e.target.value;changePage=0;render();}if(e.target.id==='routeSource'){routeChoice=e.target.value;invalidateSecurity();render();}if(e.target.id==='routeMode'){routeMode=e.target.value;invalidateSecurity();render();}if(e.target.id==='pilotSelect'){pilotChoice=e.target.value;pilotPhase='prepare';pilotImages={};pilotSA='';invalidateSecurity();render();}if(e.target.dataset.mapping){if(e.target.value)mappings[e.target.dataset.mapping]=e.target.value;else delete mappings[e.target.dataset.mapping];invalidateSecurity();render();}if(e.target.id==='severity'){severity=e.target.value;updateResults();}if(e.target.id==='category'){category=e.target.value;updateResults();}if(e.target.id==='appSelect')graph(e.target.value);if(e.target.dataset.check){e.target.checked?checks.add(e.target.dataset.check):checks.delete(e.target.dataset.check);}});
document.addEventListener('submit',e=>{if(e.target.id==='executionForm'){e.preventDefault();try{const f=e.target.elements;executionSettings=X.settings(Object.fromEntries(['smokePort','smokePath','expectedStatus','maxLatencyMs','smokeMarker','rolloutSeconds'].map(k=>[k,f[k].value])));invalidateSecurity();render();toast('Pilot execution settings saved; previous scoped observations cleared');}catch(error){executionError=error.message;render();}}if(e.target.id==='waveDefinitionForm'){e.preventDefault();try{const fields=e.target.elements,edited={id:waveChoice,...Object.fromEntries(['name','owner','entryCriteria','exitCriteria','rollback'].map(k=>[k,fields[k].value]))};waveSettings=Q.settings(raw,{...waveSettings,waves:waveSettings.waves.map(w=>w.id===waveChoice?edited:w)});waveError='';render();toast('Wave definition saved as a planning record');}catch(error){waveError=error.message;render();}}if(e.target.id==='waveAssignmentForm'){e.preventDefault();try{const f=e.target.elements,record={waveId:f.waveId.value,application:f.application.value,owner:f.owner.value,dependsOn:Array.from(f.dependsOn.selectedOptions).map(x=>x.value),notes:f.notes.value};waveSettings=Q.settings(raw,{...waveSettings,assignments:{...waveSettings.assignments,[waveWorkload]:record}});waveError='';render();toast('Workload assignment saved; sequencing requires owner review');}catch(error){waveError=error.message;render();}}if(e.target.id==='adoptSnapshotForm'){e.preventDefault();try{adoptStagedSnapshot(e.target.elements.identityReviewed?.checked===true);}catch(error){changeError=error.message;render();}}if(e.target.id==='acceptanceContextsForm'){e.preventDefault();try{acceptanceSettings=A.settings({...acceptanceSettings,sourceContext:e.target.elements.sourceContext.value,targetContext:e.target.elements.targetContext.value});invalidateSecurity();render();toast('Contexts updated; prior evidence cleared');}catch(error){acceptanceError=error.message;render();}}if(e.target.id==='acceptanceCaseForm'){e.preventDefault();try{const cases={...acceptanceSettings.cases,[acceptanceChoice]:{owner:e.target.elements.owner.value,procedure:e.target.elements.procedure.value,expected:e.target.elements.expected.value}};acceptanceSettings=A.settings({...acceptanceSettings,cases});invalidateSecurity();render();toast('Acceptance case updated; prior evidence cleared');}catch(error){acceptanceError=error.message;render();}}if(e.target.id==='targetChecksForm'){e.preventDefault();targetCheckSettings=C.settings({context:e.target.elements.context.value,includeRouting:e.target.elements.includeRouting.checked});invalidateSecurity();render();toast('Preflight scope updated; previous observations cleared');}if(e.target.id==='gitopsForm'){e.preventDefault();try{const candidate=Object.fromEntries(new FormData(e.target));candidate.includeRouting=e.target.elements.includeRouting.checked;gitopsSettings=G.settings(candidate);gitopsError='';invalidateSecurity();render();toast('GitOps draft updated; no repository or cluster action performed');}catch(error){gitopsError=error.message;render();}}if(e.target.id==='storageForm'){e.preventDefault();storageSettings[storageChoice]=Object.fromEntries(new FormData(e.target));invalidateSecurity();render();toast('Stateful plan saved in this session; save project JSON to preserve it');}if(e.target.id==='projectForm'){e.preventDefault();projectName=e.target.elements.name.value.trim()||'VKS migration project';projectNotes=e.target.elements.notes.value;render();toast('Project details updated; save a snapshot to keep them');}if(e.target.id==='securityForm'){e.preventDefault();securityDecisions[securityChoice]=Object.fromEntries(new FormData(e.target));invalidateSecurity();render();toast('Security plan revision updated; previous evidence cleared');}if(e.target.id==='routingForm'){e.preventDefault();const f=e.target.elements;routeMode=f.mode.value;routeClass=f.ingressClass?.value.trim()||'';routeGateway=f.gateway?.value.trim()||'';routeGatewayNS=f.gatewayNamespace?.value.trim()||'';routeListener=f.listener?.value.trim()||'';invalidateSecurity();render();toast('Routing draft updated; traffic remains unverified');}if(e.target.id==='imageForm'){e.preventDefault();imageStrategy=e.target.elements.policy.value;imagePrefix=e.target.elements.prefix.value.trim();imageOverrides={};for(const field of e.target.querySelectorAll('[data-image-source]'))if(field.value.trim())imageOverrides[field.dataset.imageSource]=field.value.trim();clearImageEvidence();profile.imagePolicy=imageStrategy;report=E.analyze(raw,effectiveProfile());render();toast('Image plan updated; previous registry evidence cleared');}if(e.target.id==='pilotForm'){e.preventDefault();pilotImages={};for(const field of e.target.querySelectorAll('[data-source-image]'))pilotImages[field.dataset.sourceImage]=field.value.trim();pilotSA=e.target.elements.serviceAccount.value.trim();invalidateSecurity();render();toast('Draft updated; prerequisites remain unverified');}if(e.target.id==='targetForm'){e.preventDefault();profile=Object.fromEntries(new FormData(e.target));invalidateSecurity();imageStrategy=profile.imagePolicy;imageOverrides={};clearImageEvidence();checks.clear();report=E.analyze(raw,effectiveProfile());render();toast('Assessment refreshed with destination assumptions');}});
